-- GENERATED by `wfj generate` from data/quest/quest-0095.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [95006] = { "Potere rubato", "Parla con Orokai quando sei pront<o/a> a scoprire cosa ha imparato dal Ramo Debolmente Luminoso.", "<Orokai chiude gli occhi e resta perfettamente immobile mentre comunica con il ramo. Senti sulla pelle il pizzicore pungente della magia mentre lo fa.>\n\nOh cielo, piccolo mortale. Le storie che questo ramo ha da raccontare...\n\nVieni, lascia che te le mostri.", nil, nil, 0x5a97a2ce, 0x79aa876f, 0x5e056de7, nil, nil, "...mm" },
  [95026] = { "Addio al morbo", "Elimina $N1 Soldato Dimenticato e $N2 Famelico Scorticacarne.", "Scappare dalla guerra non vuol dire che qui siamo al sicuro, eh. Quelle creature a est tormentano la zona da sempre.\n\nForse tu pronto per una sfida, eh?\n\nAbbattile. Nessuno sentirà la loro mancanza, tanto.", nil, nil, 0x51840a50, 0xb93184f5, 0x3762e429, nil, nil, "...mm" },
  [95027] = { "Piume in volo", "Dirigiti a sud nella valle e raccogli piume di gufo dai loro nidi.", "Abbiamo sempre bisogno di più frecce per cacciare e combattere e, per le piume, usiamo le piume bianche del gufo di Hyjal. Sono naturalmente soffici e morbide, ma io le irrigidisco con una miscela fatta apposta per renderle perfette per l'impennaggio.\n\nLe piume puoi prenderle dai gufi, certo, ma ne lasciano anche nei loro nidi, che trovi dappertutto a sud di qui.\n\nPortami un fascio di piume, va bene?", nil, nil, 0x4fa7c2f1, 0x10be7ced, 0x1cc5a39b, nil, nil, "...mm" },
  [95033] = { "Dall'altra parte", "Tan'jani vuole che tu parli con il ⟦Witch Doctor Uzer'i=Taumaturgo Uzer'i⟧ all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.", "Se ti stufi di queste pianure aperte, il mio vecchio amico Uzer'i cerca sempre aiuto. Passa il tempo a piegare quelle magie, ma pochi sanno che è anche un bravo cacciatore.\n\nSe ti interessa, lo trovi in fondo, all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.\n\nDigli che ti manda il vecchio Tan'jani.", nil, nil, 0x3c949346, 0x1f25c8c8, 0x1fc0fd3e, nil, nil, "...mm" },
  [95034] = { "Il debito", "Parla con Lumina Windsinger alla ⟦Sepulcher=Mausolea⟧.", "Credo che tu debba sapere che non sono stati davvero gli gnoll ad attaccarci sulla strada.\n\nIn realtà ci ha attaccati una creatura gigantesca, simile a un lupo, che ora so chiamarsi \"worgen\". Ha fatto fuori le nostre guardie ed è venuta verso di me, ma Banon si è gettato sul suo cammino. Sono riuscita a lanciare un incantesimo che ha spaventato la creatura e l'ha messa in fuga, ma Banon era già stato morso gravemente. Insisteva perché lo lasciassi lì, ma mi sono rifiutata.\n\nStavamo tornando qui zoppicando quando ci hanno trovati gli gnoll. Ciò che è successo dopo è stato terrificante...", nil, "Ora capisci. Allo stremo delle forze, dopo essere stato trafitto da una dozzina di lame gnoll, si è sollevato per colpirmi. In quell'ultimo istante i nostri sguardi si sono incrociati, e ho capito che sapeva ancora chi era e che mi riconosceva. Sapeva cosa stava succedendo, ma non aveva alcun controllo su se stesso. Quella è stata la parte peggiore.\n\nSe una cosa simile è possibile, vedrò morta la creatura che lo ha condannato, così che non possa mai più infliggere quest'orrore a un altro essere vivente. Lo giuro sul cielo sopra di noi.", 0x0ff7705c, 0x84784026, 0xdc6412d7, nil, 0xb4f8e463, "...m." },
  [95036] = { "Una lama baciata dalla luna", "Parla con Trevan Rol alla ⟦Sepulcher=Mausolea⟧ e portagli i materiali che gli servono.", "Trevan mi dice che i worgen sono una grave minaccia per gli abitanti della ⟦Silverpine Forest=Selva Pinargento⟧. Nonostante la loro forza e resistenza possono essere uccisi, ma ce n'è uno in particolare che, per una magia sconosciuta, sembra non restare mai morto.\n\nÈ quello che ci ha attaccati. È noto come Old Fire-Eye ed è il più grosso e il più crudele della sua specie. Per abbatterlo ci servirà un'arma speciale.\n\nParla con Trevan: ti darà un elenco di ciò che serve per forgiare un'arma simile.", "Affidati alla Luce perché guidi la tua lama. Ma la Luce ha bisogno di una buona lama da guidare.", "Ora che abbiamo i materiali che ci servono, ci manca solo un fabbro che forgi la lama per noi. E credo di conoscere proprio il fabbro giusto.", 0xe7da37a4, 0x4585e62b, 0xb4f5a29b, 0x1c7078a4, 0xf4085685, "....." },
  [95041] = { "Accumulatori di dati", "Raccogli 7 ⟦Gnomeregan Archival Data=Dati d'Archivio di Gnomeregan⟧ nei dintorni di Gnomeregan, poi consegnali a ⟦Jemma Quikswitch=Jemma Cambiamarcia⟧ a ⟦Ironforge=Forgiardente⟧.", "Prima di fuggire da Gnomeregan ho fatto una copia cartacea degli archivi di famiglia. Equazioni di campo arcanotecniche, progetti di scafi di sottomarini della Seconda Guerra, la ricetta del chili di nonna Quikswitch... le nostre più grandi conquiste sono in quei file.\n\nSolo una volta a ⟦Ironforge=Forgiardente⟧ ho scoperto un buco nello zaino! Mancano diverse schede perforate e, senza di loro, i dati sono troppo confusi per recuperarli.\n\nLe schede devono essere sepolte nella neve, da qualche parte fuori da Gnomeregan. Potresti trovarle? Lo so, è un tentativo disperato...", "Come procede il recupero dei dati?", "Queste schede sembrano un po' umide... ma posso lavorarci! Grazie, {name}!", 0x2ec708ec, 0xdde3bae7, 0xd738032b, 0x4bbba72e, 0x87fa01c3, "....." },
  [95042] = { "Alla ricerca della Gemma Kor", "Porta una Gemma Kor a Ulric Frostveil a ⟦Ashenvale=Valtetra⟧.", "<Un/Una> <paladino/paladina> dei Reietti... qui a ⟦Ashenvale=Valtetra⟧? Divertente.\n\nQuindi cerchi una Gemma Kor? Non mi sorprende: a volte i paladini dell'⟦Alliance=Alleanza⟧ le usano per potenziare armi e strumenti magici. Perché <un/una> <paladino/paladina> <caduto/caduta> come te dovrebbe essere diverso?\n\nSe desideri davvero una di queste gemme, devi andare a nord, nelle rovine note come ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. I naga che usano ancora le gemme si trovano là sotto. Non andare da sol<o/a>, {class}.", "Le gemme Kor possono servire a grandi atti di malvagità. Non sta a me giudicare se le tue intenzioni sono pure. A me non importa.", "Avrai senz'altro notato la corruzione che permea questa gemma. Per i tuoi scopi, la magia necessaria a dissipare il male che le streghe naga vi hanno infuso è piuttosto semplice. Un vero peccato: si potrebbe imparare molto da poteri simili.\n\nNon è che saresti dispost<o/a> ad abbandonare qualunque missione ti abbia spinto a cercare questa gemma, e a vendermela invece? Potrebbe rivelarsi preziosa per le mie... ricerche accademiche.", 0x5d353131, 0x653f65b8, 0x34bb9815, 0x3e8b8507, 0x8c1b448d, "....." },
  [95056] = { "Addio a Krol'dok!", "Scorta NAME in salvo.", nil, nil, nil, 0x063219ff, 0x1228bc5a, nil, nil, nil, "..mmm" },
  [95059] = { "Cassa di Sfrigolascintilla", "Consegna la Cassa di Sfrigolascintilla al cavaliere comandante Demar Brant a Forte Farholde.", "È ora di una consegna speciale.\n\nIl cavaliere comandante Demar Brant di Farholde aspetta questo. Per qualche motivo mi fa sempre dire il suo nome completo. Che tipo strano.\n\nComunque, lo trovi rintanato nel forte a sud-ovest di qui. Una fortezza di pietra enorme. Non puoi sbagliare.", nil, "Quel goblin non è nient'altro che un mezzo per raggiungere un fine. Certi affari vanno fatti per garantire la sicurezza e il successo della nostra gente.", 0x7845f90e, 0xa6cfa401, 0x826fc105, nil, 0x7e4bf926, "...m." },
  [95062] = { "La Cassa di Sfrigolascintilla", "Consegna la ⟦Frazzlespark's Crate=Cassa di Sfrigolascintilla⟧ a Krom'rosh a Rog'mar.", "È ora di una consegna speciale.\n\nIl vecchio Krom'rosh aspetta questo pacco a Rog'mar, poco a ovest di qui.\n\nTi consiglio di portarglielo in fretta, ma con attenzione. Perché, mi chiederai? Meglio non fare domande.", nil, "Abbiamo costruito molte relazioni per rispetto, altre per necessità.\n\nQuesti rapporti ci aiutano a raggiungere i nostri obiettivi.", 0x7845f90e, 0x0463d5db, 0xa30e26ca, nil, 0x5f5cfc83, "...m." },
  [95063] = { "Anello del Maestro del Sangue", "Sconfiggi Chub'chob, Maestro del Sangue di Bolder'ok, nell'Anello del Maestro del Sangue, poi condividi la notizia di essere il nuovo campione dell'Anello del Maestro del Sangue con Clugfist a Bolder'ok.", "Ok, ascolta bene. Hai mostrato parecchia abilità sul ring. Sei riuscito a far arrabbiare Chub'chob più di quanto le parole possano spiegare. Che fortuna non essere al tuo posto adesso.\n\nNel caso ti stessi chiedendo, devo ricordarti che la tua quota d'iscrizione non copre la morte accidentale.\n\nÈ stato un piacere conoscerti, ma da qui in avanti sei da solo, amico.\n\nIn bocca al lupo.", nil, nil, 0xa5cbf621, 0x55ee5eb3, 0x93280971, nil, nil, "...mm" },
  [95064] = { "Misure preventive", "Uccidi $N1 Recluta di Rog'mar per il guardiano Cornelius al Presidio di Terral.", "Gli orchi sono diventati una minaccia sempre più invadente da quando sono arrivati. Prima si sono presi le terre lungo il fiume e ora la loro presenza cresce nelle pianure...\n\nNon capirò mai quelli come loro, né mi importa, a dire il vero, ma che io sia dannato se permetto che pensino che ci sia altro terreno da prendersi.", nil, "Ci vorrà del tempo per rimpolpare i loro ranghi. Forse ora possiamo riprendere il controllo della zona.", 0x5d319cbd, 0x0c83fe90, 0x9ffbbadf, nil, 0x7418b03d, "...m." },
  [95065] = { "È ora di pescare", "Porta $N1 ⟦Shiny Bauble=Esca Lucente⟧ e $N2 Nightcrawlers a Gilbert Gray, al porto di ⟦Stormwind=Roccavento⟧.", "Che vista... Il meglio che un vecchio possa chiedere.\n\nI pesci abboccano eccome, adesso, ma mi è rimasta solo l'ultima esca. Non è che hai con te dell'attrezzatura da pesca in più? Ma certo che no, perdonami. Mi entusiasmo così tanto all'idea di lanciare un'altra lenza che non mi è venuto in mente che forse sono uno dei pochi a portarsi dietro l'attrezzatura ovunque vada.\n\nPotresti aiutarmi a rifornirmi? Catherine Leland ha un assortimento di articoli da pesca appena a ovest del ⟦Trade District=Quartiere del Commercio⟧, lungo i canali. Dille che ti manda il vecchio Gray.", "Hai preso l'attrezzatura da pesca?", "Tempismo perfetto! Ne ho preso uno grosso con l'ultima esca. Finora è una gran giornata. Qui abboccano davvero!\n\nFacciamo così: visto che sei stat<o/a> così gentile da tenere in attività questo vecchio, che ne dici di qualche pesce per il viaggio?", 0x50ff1618, 0x1ca3ae56, 0x4f6c7d2d, 0x630eca56, 0x7cc547b8, "....." },
  [95066] = { "La situazione di Rog'mar", "Consegna il rapporto a Demar Brant a Forte Farholde.", "Il messaggio che abbiamo recapitato è chiaro.\n\nTorna da Brant nel forte e mostragli il rapporto. Sono certo che sarà soddisfatto dei nostri progressi.", nil, "Sembra che Cornelius si sia dimostrato molto efficace nel suo incarico, con il tuo aiuto, naturalmente.\n\nPurtroppo i festeggiamenti distraggono dal lavoro che ci resta, esponendoci a inutili vulnerabilità, ma... forse un momento per riflettere sui nostri progressi è doveroso.", 0x6e3e67b7, 0x9da61674, 0x1a83c1a3, nil, 0x21204f62, "...m." },
  [95107] = { "La caduta di Ruggitofondo", "Uccidi il capotribù Ruggitofondo e riporta il suo bastone all'anziano Parlapino alla Tana dei Pelledura.", "Un capo dei Legnomorto, Ruggitofondo, ringhia nelle profondità della loro tana. Un tempo non apparteneva a nessuna tana e, in una notte di cattivo sangue, è caduto sotto i loro incantesimi.\n\nOra si nutre della loro linfa acida, con un ruggito maledetto due volte più forte.\n\nVai. Metti fine alle sue vie impure. Prendi il suo bastone e portalo qui, così saprò che non lo impugna più.", nil, nil, 0x1bae7ed4, 0xfc136e13, 0x1215b7d7, nil, nil, "...mm" },
  [95108] = { "Miscela mistica", "Uccidi due Mistici della Morte Legnomorto e distruggi due Calderoni Legnomorto nella Tana Legnomorto.", "Con la vista lunga, abbiamo visto la loro tana. I Legnomorto preparano oscuri riti nei loro calderoni. Danno questo intruglio impuro ai loro piccoli, perché radici cattive attecchiscano. Poi imparano a combattere con vie vili.\n\nVai, ferma questa diffusione. Uccidi gli oscuri e distruggi il loro stufato.", nil, nil, 0x0a0d88f0, 0xdc883544, 0x1aebf69f, nil, nil, "...mm" },
  [95111] = { "Un talento sottovalutato", "Parla con ⟦Ott=Nov⟧ e chiedigli di forgiare la tua lama.", "Al ⟦Tarren Mill=Mulino di Tarren⟧ c'è un fabbro d'armi di nome ⟦Ott=Nov⟧. A detta di tutti è un fabbro qualunque, che vende lame semplici ai viaggiatori. Io stesso ho comprato una spada da lui e, quando qualche tempo dopo l'ho portata a Sepulcra per la manutenzione, i fabbri di lì sono rimasti sorpresi dalla sua qualità. Pensavano che venisse da un celebre mastro fabbro, ma no: era soltanto ⟦Ott=Nov⟧.\n\nVorrei dare a questo orco l'occasione di fare qualcosa di davvero speciale. Porta i materiali a ⟦Ott=Nov⟧, al ⟦Tarren Mill=Mulino di Tarren⟧, e offrigli la commissione.", "Ti serve una lama, {class}?", "Interessante. Non credo che qualcuno mi abbia mai chiesto di eseguire una commissione su misura. Di solito faccio solo armi umili e funzionali, a modo mio. Non è granché, ma è un lavoro onesto e non cerco riconoscimenti né gloria.\n\nSono felice di provarci, ma perché sei venut<o/a> da me per questo? A ⟦Undercity=Sepulcra⟧ ci sono tanti fabbri che accetterebbero lavori su misura come questo.", 0x2c5a8af0, 0x57d2ed34, 0x9137acf7, 0x45d644e4, 0xc6b81f00, "....." },
  [95118] = { "Selvaggi d'Acqua Salata", "Uccidi $N1 ⟦Murloc Oracle=Murloc Oracolo⟧ e $N2 ⟦Murloc Warrior=Murloc Guerriero⟧ lungo la ⟦Eastwind Shore=Costa Vento di Levante⟧.", "Murloc, murloc, murloc! Non sento parlare d'altro: dai marinai, dai pescatori, perfino dai miei figli! Tutti mi stanno addosso per colpa loro! Sono una seccatura, lo ammetto, ma io qui ho un porto da mandare avanti!\n\nDai una mano a un poveretto, eh? Fai fuori un po' di quelle bestiacce e ne varrà la pena, te lo garantisco.", nil, "Te ne sei occupat<o/a>? Bene! Sono certo che presto ne torneranno altri, ma almeno fino ad allora potrò avere un po' di pace e tranquillità.", 0xb5ac9836, 0x8cfe2625, 0x6546b7aa, nil, 0x57badcb8, "...m." },
  [95119] = { "Concorrenza sleale", "Uccidi $N1 Bucaniere del Mare d'Oriente e $N2 Moschettiere del Mare d'Oriente lungo la Costa Vento di Levante, a nord del Porto Polveraccesa.", "Conosci la ciurma del Mare d'Oriente? Una banda davvero poco raccomandabile, e lo dice uno che gestisce un posto chiamato \"Porto Polveraccesa\".\n\nSono distruttivi, assetati di sangue e, peggio di tutto, mi mangiano i profitti. Rubano carichi e affondano navi, e in entrambi i casi finisce che mi costa un sacco di soldi!\n\nDobbiamo smantellare tutta la loro operazione, a cominciare da quelli più vicini a qui. Li trovi lungo le spiagge a nord.", nil, "Ben fatto, {race}. Ora puntiamo al pesce più grosso.", 0x4b93ed2b, 0xf0a3a238, 0xd3a43092, nil, 0x769f6dfc, "...m." },
  [95120] = { "RICERCATO: Vecchio Pasturamarcia", "Porta la prova della morte del ⟦Old Rot-Chum=Vecchio Pasturamarcia⟧ al ⟦Wharfmaster Whizzbuzz=Capitano del Porto Ronzafischio⟧.", "Attenzione, marinai e nuotatori! Un murloc particolarmente aggressivo, soprannominato «⟦Old Rot-Chum=Vecchio Pasturamarcia⟧» dai pescatori del posto, è stato visto attaccare barche a remi e altre piccole imbarcazioni nelle acque a sud, vicino a un gruppo di isole infestate dai murloc.\n\nIl ⟦Wharfmaster Whizzbuzz=Capitano del Porto Ronzafischio⟧ offre una ricompensa in cambio di una prova della morte della creatura.", "Ho un sacco di cose da fare, {race}, sbrigati.", "Be', una cosa in meno di cui preoccuparsi da queste parti, ti sono certamente debitore. Tieni, non spenderlo tutto in un posto solo.", 0x41ad0257, 0xe060fa56, 0x8fcb05bb, 0xc6b86168, 0x16be8e84, "....." },
  [95121] = { "Un Assaggio di Mare", "Raccogli $N1 ⟦Murloc Eye=Occhio di Murloc⟧ e $N2 pezzi di ⟦Sand Crawler Meat=Carne di Crostaceo delle Sabbie⟧ per ⟦Fimbo Greasemitz=Fimbo Manunta⟧.", "Benvenut<o/a> al caffè sull'acqua di Fimbo! Il menu di oggi è cinghiale arrosto e pesce arrosto... come tutti i giorni...\n\nQuesto menu ha un disperato bisogno di una rinfrescata. Ho adocchiato la ricetta di un nuovo stufato di mare, ma mi serve un po' di carne fresca. Qualche occhio di murloc e un po' di carne di granchio dovrebbero bastare.\n\nTrovi entrambi lungo le spiagge qui vicino. Non c'è niente di meglio dei buoni vecchi ingredienti locali!", "Il trucco con gli occhi di murloc è cuocerli molto in fretta. Così senti ancora il sapore della salamoia!", "Tagli deliziosi, mio aiuto cuoco. Una pentola di zuppa di mare in arrivo!", 0x424dd627, 0x28bb63da, 0x34fec1a6, 0xc3ab7fce, 0xf3cb431a, "....." },
  [95122] = { "Espansione incontrollata", "Uccidi $N1 Predone del Mare d'Oriente e $N2 Bombardiere del Mare d'Oriente per il capitano del porto Ronzafischio.", "I pirati del Mare d'Oriente che hai fatto fuori, per quanto pericolosi, erano solo pesci piccoli. Hanno fratelli d'armi più grossi e più cattivi a nord di qui. Hanno saccheggiato Casavento: hanno preso tutto il bottino che potevano e poi l'hanno data alle fiamme.\n\nVanno fermati prima che il loro territorio si spinga ancora più nell'entroterra. Sfoltisci i loro ranghi perché non succeda.", nil, "Vedo che non hai paura di sporcarti le mani. Mi piace.\n\nGrazie a te, le cose si stanno mettendo bene per farla finita con quei furfanti una volta per tutte.", 0x8e943689, 0xf053b390, 0x2291e4d1, nil, 0x392f18c0, "...m." },
  [95123] = { "Una bella botta, cani rognosi!", "Ruba $N1 Barile di Polvere del Mare d'Oriente per il capitano del porto Ronzafischio.", "Per quanto adori vedere rotolare le teste del Mare d'Oriente, dobbiamo anche far fuori le loro navi. Non possiamo lasciare che vadano a cercare rinforzi, no?\n\nHo un piano per questo, ma ci servirà della polvere da sparo. TANTA.\n\nI pirati probabilmente ne tengono un po' vicino a Windstead, appena demolita, a nord. Vedi se riesci a metterci le mani sopra. Ti spiegherò il resto più tardi.", "Hai già la polvere da sparo?", "<Ronzafischio emette un fischio di sorpresa.>\n\nWow, sono enormi! Non vedo l'ora di accenderli e di mandare quei pirati in orbita!", 0x36103d46, 0x7a2e25da, 0x60929911, 0x9e32bcad, 0xa08fc1a1, "....." },
  [95124] = { "Ammiraglia Lamora", "Uccidi l'ammiraglia Lamora, trova il suo bottino nascosto e riportalo al capitano del porto Ronzafischio.", "Ora è il momento di andare a caccia del pezzo grosso in persona: l'ammiraglia Lamora. Ovviamente voglio la sua morte, ma mi serve anche qualcosina in più da parte sua.\n\nVisto che tutti i suoi saccheggi mi sono costati una fortuna, mi pare giusto rifarmi almeno in parte.\n\nLamora si trova su una delle navi del Mare d'Oriente a nord-est di qui. Scopri quale e dove tiene il bottino a bordo. Portami tutto quello che ha. Se è sotto chiave, la chiave dovrebbe averla addosso.", nil, nil, 0x7f2fde5c, 0xbe87cf02, 0xb7aa8e23, nil, nil, "...mm" },
  [95125] = { "Il capolavoro di Ott", "Guarda ⟦Ott=Nov⟧ mentre forgia la tua lama.", "Sono materiali davvero pregiati, {class}. Mi onori lasciandomi forgiare questa lama per te, e spero solo di essere all'altezza delle tue aspettative.\n\nTi prego, fatti indietro, così posso cominciare la forgiatura.", nil, "Questa lama è il mio lavoro migliore e spero che ti serva bene nei tuoi viaggi. Grazie ancora per questa occasione.\n\nAka'Magosh, amic<o/a>.", 0x2af2ae36, 0xa5330aaf, 0xa0a0368f, nil, 0xee452c14, "...m." },
  [95126] = { "La Moonsilver Blade", "Porta Ott's Masterwork a Trevan Rol nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Ecco la lama. Hai detto che ti ha mandato un paladino di nome Trevan? Quando lo rivedrai, ringrazialo da parte mia per questa occasione. Va' con onore, amic<o/a>.", "⟦Ott=Nov⟧ è riuscito a portare a termine la commissione?", "<Trevan prende la lama e la esamina con cura.>\n\nAndrà benissimo, {name}. Sapevo che ⟦Ott=Nov⟧ era capace di creare qualcosa di davvero grande.\n\nOra non resta che uccidere quella bestia. Parla con Lumina quando sei pront<o/a>.", 0x774c6075, 0xb9d5e27a, 0xac0b5a01, 0xaf39b5e9, 0x469d97a1, "....." },
  [95140] = { nil, "Usa la ⟦Moonsilver Blade=Lama d'Argento Lunare⟧ per distruggere Old Fire-Eye nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Vedo che ora hai la tua arma, {class}. Prego che non ti tradisca.\n\nLa gente del posto dice che Old Fire-Eye caccia in un'ampia zona a sud di qui e che di solito lo si trova vicino ai cancelli di Gilneas. Trovalo e usa la tua nuova lama per farla finita con lui. Quando avrai finito, torna e avrai la gratitudine dei Windshaper.", "È fatta? La bestia è morta?", "Grazie, {name}. Ora Banon può riposare in pace.\n\nSe me lo permetti, credo di poter infondere nella tua lama, appena bagnata di sangue, una piccola parte della magia del mio popolo.\n\n<Gli occhi di Lumina Windsinger cominciano a brillare di un azzurro vivido mentre tocca la lama insanguinata che hai in mano.>\n\nÈ fatto. È poca cosa, e difficilmente potrei migliorare una lama così magnifica. In ogni caso, pregherò i venti perché ti serva bene, {class}.", 0x1db24010, 0xee598827, 0x2f1bb8e0, 0x95a43f2e, 0xb76eccca, "e...." },
  [95141] = { "Rapporto a Rog'mar", "Presentati a Krom'rosh all'avamposto di Rog'mar, nelle Radure del Fiume.", "Lontano a nord-est oltre ⟦Stonard=Pietrachiusa⟧ si trova una terra contesa lungo la costa orientale, nota come Radure del Fiume.\n\nIn molti hanno cercato di rivendicare queste terre, ma pochi ci sono riusciti. C'è però uno la cui esperienza nel combattere i nostri nemici è bastata a fondare un piccolo avamposto noto come Rog'mar. Dopo innumerevoli attacchi, è ancora in piedi.\n\nPer quanto spietato possa essere Krom'rosh, la sua volontà è stata di grande servizio ai nostri alleati. Se è battaglia che cerchi, dirigiti a nord-est e cerca questo nostro vecchio amico.", nil, nil, 0xace9c387, 0x34de9fdc, 0xe783d97b, nil, nil, "...mm" },
  [95143] = { "Alla ricerca di Tan'jani", "Trova Tan'jani a Rog'mar, nelle Radure del Fiume.", "Ti ho osservato, {name}. Te la cavi bene qui fuori. Forse ti interesserebbe aiutarmi a ritrovare mio fratello, Tan'jani.\n\nCercava sempre qualcosa... cosa, non lo so. Da quando è partito ho ricevuto due messaggi. Il primo da un altro viaggiatore, che mi faceva sapere di aver incontrato Tan'jani da qualche parte a sud di Loch Modan. Il secondo era una lettera macchiata di sangue che menzionava le Radure del Fiume e un posto chiamato Rog'mar, ancora più a sud. Il resto era illeggibile.\n\nPensi di riuscire a trovarlo per me?", nil, "Tor'gan ti ha mandato fin quaggiù a cercarmi? Lui sempre pensa a me. Spero di vederlo presto.\n\nMa io non lascio mio posto finché lavoro non è finito, sì? Lunga storia con Krom'rosh. Quasi lunga come con Tor'gan. Quasi.\n\nQui tutto bene, amico. Niente di cui preoccuparsi. Tranne quelli del Crepuscolo che sempre combinano guai. Il vecchio Krom'rosh vicino al grande fuoco può dirti di più.", 0x5f1d7210, 0x85b64451, 0x30ffd973, nil, 0x553169ea, "...m." },
  [95144] = { "Consegna Oltremare", "Consegna la ⟦Fizzgrimble's Mysterious Crate=Cassa Misteriosa di Raschiastrati⟧ a ⟦Friz Frazzlespark=Friz Sfrigolascintilla⟧ a ⟦Powderfuse Port=Porto Polveraccesa⟧, nelle ⟦Riverglades=Radure del Fiume⟧.", "Ehi, amico. Ho un pacco da far arrivare a un mio vecchio amico. Qualunque cosa succeda...\n\nNON APRIRE IL PACCO!\n\nPortalo, con attenzione, a ⟦Friz Frazzlespark=Friz Sfrigolascintilla⟧, oltre il mare, al nostro porto gemello nelle ⟦Riverglades=Radure del Fiume⟧. E prima che tu me lo chieda, no, non ti consiglio di andarci a nuoto. All'ultimo che ci ha provato non è andata benissimo. Ah, e non inclinarlo, non scuoterlo e non fare movimenti bruschi.\n\nTi consiglio di andare a est, al ⟦Steamwheedle Port=Porto degli Spargifumo⟧. Di solito la nave che parte da lì garantisce una traversata sicura.\n\nBuona fortuna!", nil, "Un pacco dal mio vecchio amico Raschiastrati? Proprio quello che aspettavo!\n\nNon l'hai scosso, inclinato o fatto movimenti bruschi mentre lo portavi, vero?\n\nTi dispiacerebbe voltarti mentre do un'occhiata dentro? Non vorrei che mi rovinassi la sorpresa.", 0x69392ac7, 0xd1577f7c, 0xce15a97d, nil, 0xcdfb23b6, "...m." },
  [95147] = { "L'esploratore disperso", "Consegna il messaggio di Bolain al capitano Dalton alla Guardia Meridionale.", "Tu... da dove arrivi? Non dovresti essere qui!\n\n<Bolain lotta contro il dolore: è pieno di lividi, malconcio, con un morso infetto a una gamba.>\n\nPorta questo a Dalton. Vai a nord lungo la strada e poi a est, dove le pianure si aprono più di questo squarcio nella mia dannata gamba. Ti direi di dirgli che aveva ragione, ma non gli darò questa soddisfazione... almeno non finché non sarò morto.\n\nOdio queste dannate colline!", nil, "Bolain è andato dove?? Quel figlio di--gli avevo detto di non andare da solo.\n\nA quanto pare alcuni dei nostri sottovalutano ancora quei maledetti gnoll. Il cavaliere comandante vorrà saperlo subito.", 0xb3678d9a, 0xc6cc93b8, 0xd0ee412a, nil, 0x9ecdaca1, "...m." },
  [95148] = { "Rapporto sugli Gnoll della Guardia Meridionale", "Consegna il Rapporto sugli Gnoll della Guardia Meridionale al cavaliere comandante a Forte Farholde.", "Per quanto mi piacerebbe consegnare personalmente il messaggio imbrattato di sangue al cavaliere comandante, vorrei anche mantenere il mio posto. L'ho ripulito un po', così è meno... beh, sanguinoso.\n\nViste le recenti rivolte degli gnoll, temo che il compito di consegnare la notizia spetti a te.", nil, "È una notizia sfortunata, ma non è una sorpresa. Da anni la presenza degli gnoll tormenta queste terre.\n\nQuando siamo arrivati, le battaglie infuriavano in continue scaramucce per le colline e le pianure basse. Solo dopo molte perdite siamo riusciti a riprenderci e a tenere la posizione.\n\nMi assicurerò che Dalton e i suoi uomini ricevano razioni extra, armi e, per il momento, fanti. Non possiamo rischiare che gli gnoll violino di nuovo il nostro territorio.", 0x850d7dbd, 0x75b74caf, 0xb4923963, nil, 0x39e7ff10, "...m." },
  [95156] = { "Imbottiscili e infilzali", "Raccogli $N1 fasci di fieno per Ember al campo di addestramento.", "I nostri manichini d'addestramento iniziano a mostrare segni evidenti di usura. Se non li sistemiamo presto temo che le nostre reclute possano non essere pronte alla battaglia.\n\nSe non l'hai notata mentre arrivavi, appena fuori dal forte c'è una piccola fattoria gestita da un uomo di nome Wheeler. Potrebbe avere qualche balla di fieno in più di cui è disposto a separarsi.\n\nMi assicurerò che venga compensato, se riesce a risparmiare provviste per i nostri sforzi.", "Hai trovato ciò che cercavi?", "Sistemeremo subito qualche nuovo bersaglio.", 0x25a2dad2, 0x3edfe8e2, 0xb9cc71e2, 0xa39870fb, 0x08dfc511, "....." },
  [95161] = { "Ricorda che ti voglio bene", "Consegna la ⟦Blood-Stained Letter=Lettera Macchiata di Sangue⟧ ad ⟦Avette Fellwood=Avette Legnocurvo⟧ a ⟦Duskwood=Boscovespro⟧.", "Se cerchi Jeremy Heartweaver, la cosa migliore è parlare con la sua nuova madre adottiva, ⟦Avette Fellwood=Avette Legnocurvo⟧, giù a ⟦Duskwood=Boscovespro⟧. Una donna dolce. Probabilmente le serve un altro paio di mani per il suo lavoro, ma è sempre meglio che restare all'orfanotrofio.\n\nSe vedi il piccolo Jeremy, digli che pensiamo tutti a lui, d'accordo?", "Sì? Di cosa hai bisogno?", "Oh, no...\n\nÈ gentile da parte tua portarmela, ma non credo che Jeremy sia pronto a vederla. La direttrice Nightingale ha detto che il mio piccolo Jeremy non parla più dall'attacco a Lordaeron, e non intendo forzarlo adesso. Mostrargliela gli causerebbe solo altro dolore.\n\nNon guardarmi così. Non gli nasconderò il suo passato, ma ha bisogno di tempo per guarire. Gliela darò quando sarà più grande. Grazie di essere passat<o/a>, ma credo sia ora che tu vada.", 0x920a601f, 0xa5aac85c, 0xab5e3e2b, 0x664e4a5c, 0xbb9d2166, "....." },
  [95162] = { "Il raccolto degli Zannapallida", "Raccogli $N1 pezzi di carne di cinghiale per Na'zok vicino a Bolder'ok.", "Con così poca terra non rivendicata dagli umani o dal ⟦Twilight's Hammer=Martello del Crepuscolo⟧, questo ranch è una delle nostre pochissime fonti di cibo. Gli ogre non sono granché come contadini, ma adorano un buon arrosto di zannapallida e hanno accettato di lasciarmi restare finché la carne continua ad arrivare.\n\nMan mano che la nostra guerra avanza, la richiesta di cibo non fa che aumentare. Ormai ho a malapena abbastanza cibo per evitare che questi ogre mi guardino come se fossi il loro prossimo pasto.\n\nSe vogliamo avere abbastanza carne per Rog'mar, mi servirà il tuo aiuto con il raccolto.", nil, nil, 0xf781fc8d, 0x7dc71fe6, 0x4717ae1f, nil, nil, "...mm" },
  [95163] = { "Respingerli", "Riporta $N1 giovani Zannapallida alla fattoria di Na'zok vicino a Bolder'ok.", "Come vedi, ci sono più maiali sparsi per la valle che nei loro recinti. Ingozzapancia non è stato il bracciante ideale, ma tiene lontani gli umani.\n\nAlcuni dei piccoli sono scappati oltre il fiume. Sono ancora troppo piccoli per essere macellati sul campo, quindi dobbiamo riportarli qui. Prendi questo bastone e dagli una bella sculacciata! Dovrebbe farli correre di nuovo ai loro recinti.", nil, nil, 0xa0591727, 0x318c14ec, 0x3b0017c3, nil, nil, "...mm" },
  [95165] = { "Addio, canaglie!", "Piazza una carica esplosiva a distanza su ciascuna delle tre barche del Mare d'Oriente.", "Allora, ecco come affonderemo quelle navi.\n\nPosso usare la polvere da sparo che hai rubato per fabbricare cariche a tempo. Tutto quello che devi fare è salire su ogni nave del Mare d'Oriente e piazzare una carica nello scafo di ciascuna. Cerca un punto vicino ai loro cannoni: quella polvere renderà i nostri esplosivi ancora più potenti. Una volta piazzate le cariche, togliti di lì e io premerò il detonatore!\n\nL'eleganza del piano sta nella sua semplicità, non trovi?", nil, nil, 0x44b992a0, 0x7579e8e1, 0x23f954ec, nil, nil, "...mm" },
  [95181] = { "Rapporto di Ricognizione del Crepuscolo", "Consegna il messaggio di Azka a Krom'rosh a Rog'mar.", "Silenzio!\n\n<Azka sbotta, spostando lo sguardo nella tua direzione.>\n\nTi taglio la testa prima che tu riveli la mia posizione ai cultisti.\n\nBada a dove metti i piedi e tieni un tono basso quando attraversi queste colline. Altrimenti manderò un rapporto a Krom'rosh dicendo che un altro dei nostri è stato catturato.\n\nOra prendi questo e levati di torno in fretta... e in silenzio! Krom'rosh aspetta questo rapporto. Trovi lui e gli altri all'avamposto nell'entroterra, a est.", nil, nil, 0x39bd1852, 0x29122aee, 0x73719bab, nil, nil, "...mm" },
  [95183] = { "Primo passo: la pietra", "Raccogli $N1 Bella Pietra per Hamur a Bolder'ok.", "Tu vuoi arma ogre? Io non sapere. Tu piccolo. Non riesci tenere bene.\n\nTu porti a Hamur più pietre, io faccio a te arma piccola. Buona per creatura piccola.\n\nTrova belle pietre per arma buona. Hamur ha occhio fine. Non qualsiasi pietra va bene. Trova pietre vicino a fiume fuori Bolder'ok.", nil, nil, 0x84960ab5, 0x839322c3, 0x51d160bd, nil, nil, "...mm" },
  [95184] = { "La più affilata delle lame", "Porta $N1 Pietra da Affilatura Solida a Ember Soffialama al campo di addestramento di Farholde.", "Il rigore dell'addestramento al combattimento è una cosa, ma queste reclute non comprendono ancora la differenza tra una spada d'addestramento e la lama ben curata di un veterano esperto.\n\nCredo sia il momento di mostrare alle nostre reclute come una lama affilata possa fare la differenza tra la vittoria e la morte.\n\nSe riesci a trovarci qualche pietra per affilare, la useremo bene. Ci sono certi artigiani noti per studiare questo mestiere. Ti suggerirei di cominciare da loro.", nil, nil, 0xa2463757, 0xba047dbd, 0xab9be8a8, nil, nil, "...mm" },
  [95189] = { "⟦Crest of Lordaeron=Stemma di Lordaeron⟧", "Riporta lo ⟦Crest of Lordaeron=Stemma di Lordaeron⟧ a ⟦Lady Dena Kennedy=Dama Dena Kennedy⟧ a ⟦Stormwind City=Roccavento⟧.", "<Uno stemma consunto che raffigura il simbolo di Lordaeron. Con così poche reliquie rimaste dopo la caduta del regno, qualcuno a ⟦Stormwind=Roccavento⟧ sarebbe molto ansioso di metterci le mani sopra.>", "Benvenut<o/a> alla galleria. Sentiti libero di dare un'occhiata.", "Come hai fatto a trovarlo? È in condizioni notevoli... tutto considerato.\n\nGrazie per aver restituito questo pezzo di storia dell'⟦Alliance=Alleanza⟧, {class}. Metterò i miei migliori al lavoro per restaurarlo subito.", 0x98ec1516, 0xea3f7a39, 0x6f2a4873, 0x2b473541, 0x7343f88c, "....." },
  [95194] = { "Il nostro uomo a Theramore", "Cerca l'agente dell'⟦SI:7=IR:7⟧ di stanza sull'⟦Theramore Isle=Isola di Theramore⟧.", "Salute, {name}. C'è una questione in cui l'⟦SI:7=IR:7⟧ potrebbe avere bisogno del tuo aiuto. Il nostro uomo sull'⟦Theramore Isle=Isola di Theramore⟧ ci riferisce che i fanti di marina di Jaina Marefiero hanno appena portato dentro un uomo trovato arenato sulla riva.\n\nDi norma non ci interesserebbe granché, ma pare che quest'uomo abbia detto ai fanti di marina di essere nientemeno che il re di ⟦Stormwind=Roccavento⟧, Varian Wrynn. Vai a Theramore e incontra un nano di nome Sully alla locanda. Ti aspetta e ti darà istruzioni quando arriverai.\n\nScopri cosa sta succedendo.", nil, "Ti ha mandato Shaw, quindi? Bene. Mi chiedevo se Renzik avesse ricevuto il mio messaggio. Su, andiamo, qui non è sicuro parlare.", 0x2e7985ad, 0x1f9f3a4e, 0x91c417e5, nil, 0x104a6512, "...m." },
  [95195] = { "⟦Bloodied Insignia=Fregio Insanguinato⟧", "Raccogli $N1 Bloodied Insignia e portale al generale Marcus Jonathan a ⟦Stormwind City=Roccavento⟧.", "<La vecchia insegna dell'⟦Alliance=Alleanza⟧ sembra essere appartenuta a un soldato di Lordaeron. Queste rovine sono probabilmente piene di medaglie simili, che i parenti ancora in vita sarebbero grati di riavere.>", "Sembri portare un pesante fardello, {name}. Di che si tratta?", "Il tuo istinto di portarmele non era infondato. Quando Lordaeron cadde sotto il Flagello, molti fuggirono per rifugiarsi qui a ⟦Stormwind=Roccavento⟧. Probabilmente ne restano pochi che possano reclamare di persona queste insegne.\n\nIl tuo servizio a ⟦Stormwind=Roccavento⟧ merita un encomio, {name}. Comincerò subito a consegnare questi pegni ai parenti più stretti.", 0xfb70dfc5, 0xf9dfef5a, 0x2c958367, 0x3d6daf5e, 0x351f4fdf, "....." },
  [95196] = { "Occhio alle spalle", "Incontra Sully McCleary ad ⟦Dustwallow Marsh=Acquemorte⟧ e scopri di più sulla tua missione.", "Ascoltami bene. Adesso esco da quella porta dietro di te. Tu aspetti che io sia ben lontano, e poi mi raggiungi dietro il cimitero fuori città. Bada che nessuno ti segua.", nil, "Ecco come stanno le cose, {class}. Mi serve che ti intrufoli in quella torre e scopri quel che puoi. Che ne dici?", 0x7b85e17a, 0x265dc649, 0x9b1cb4e5, nil, 0xc6a13634, "...m." },
  [95198] = { "Il ritorno del re?", "Usa il Kit di Travestimento dell'⟦SI:7=IR:7⟧ per origliare Jaina e la sua cerchia ristretta nella Torre dei Maghi di Theramore.", "Prendi questo. È un bel pezzetto di malia che i maghi di casa hanno messo insieme per un travestimento rapido. Ti farà sembrare un ⟦Kul Tiras Marine=Soldato di Kul Tiras⟧, il che dovrebbe andare benissimo per questa missione.\n\nInfiltrati nella torre e cerca di origliare qualsiasi accenno all'uomo che è stato trascinato dalle onde sulla spiaggia. Ti avverto però: non avvicinarti troppo a Jaina. Vedrebbe subito attraverso questo travestimento.\n\nTorna da me se perdi il travestimento, te ne darò uno nuovo.", "Allora?", "Quindi pare che l'umano che hanno trovato non sia il nostro uomo. Ma una prigione su Alcaz... con i Defias coinvolti? Concordo con Jaina, non è una coincidenza.\n\nSe c'è la possibilità che ciò che hai sentito sia vero e che fosse tenuto prigioniero insieme al re, dobbiamo entrare e tirarlo fuori il prima possibile. La dama Marefiero può starsene a pensarci quanto vuole, ma i miei ordini sono di intraprendere qualsiasi azione necessaria per riportare il re a ⟦Stormwind=Roccavento⟧, ed è esattamente ciò che faremo!\n\nCi stai, {name}?", 0x799184ff, 0x8c30df10, 0xbe476fd9, 0x04ce131b, 0xe4e17367, "....." },
  [95204] = { "⟦Crest of Lordaeron=Stemma di Lordaeron⟧", "Porta lo ⟦Crest of Lordaeron=Stemma di Lordaeron⟧ a ⟦Oran Snakewrithe=Oran Torciserpe⟧ a ⟦Undercity=Sepulcra⟧.", "<Uno stemma consunto che raffigura il simbolo di Lordaeron. Con così poche reliquie rimaste dopo la caduta del regno, qualcuno a ⟦Undercity=Sepulcra⟧ sarebbe molto ansioso di metterci le mani sopra.>", "Che cos'hai lì, {class}? Un bocconcino gustoso?", "<Oran morde lo stemma per accertarne l'autenticità.>\n\nGuarda un po'. Un'autentica reliquia della nostra patria. Quasi intatta, per giunta. Con questa dovremo stare molto attenti.\n\nGrazie per averci aiutato a restaurare la nostra storia, {class}. Mi assicurerò che ne abbiamo cura.", 0x98ec1516, 0x937c7b4b, 0x992e7722, 0x059931e7, 0xc46da411, "....." },
  [95212] = { "Sulle selle non si risparmia", "Raccogli 6 Pristine Leopard Pelt e consegnale alla ⟦Amberstill Ranch=Tenuta di Ambraquieta⟧.", "Ci stiamo preparando a mandare una squadra di arieti a rinforzare la spedizione di Alterac, ma abbiamo finito il materiale per fare le selle.\n\nRaccogli le pelli dei leopardi più grossi e feroci a est e portamele. Lassù fa un freddo pungente, e le nostre truppe meritano solo le pelli migliori per tenersi al caldo!", "Hai l'aria infreddolita, {class}. Come va la caccia?", "Queste pelli diventeranno selle eccellenti. Hai reso onore all'⟦Alliance=Alleanza⟧, {class}!", 0x07df31f7, 0x270babaf, 0xb5c3ab85, 0x545929d0, 0xcdcfccf7, "....." },
  [95213] = { "⟦Stolen Blasting Powder=Polvere Esplosiva Rubata⟧", "Porta il ⟦Empty Powder Keg=Barile di Polvere Vuoto⟧ al maestro della cava Thesten, alla ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.", "Sul barile c'è un timbro:\n\nPOLVERE ESPLOSIVA - PERICOLO - NON MANEGGIARE - PERICOLO - SOLO CON AUTORIZZAZIONE DEL CAPOCAVA - PERICOLO\n\nHai la brutta sensazione che i trogg non dovrebbero averla. Sarebbe meglio avvisare la cava al più presto.", "Che cos'hai lì?", "<Il nano impallidisce quando vede il barile vuoto.>\n\n...Dove l'hai trovato?", 0x8848eca5, 0xd56ef55e, 0xf1f411df, 0xac2369a3, 0x28899f23, "....." },
  [95214] = { "⟦Stolen Blasting Powder=Polvere Esplosiva Rubata⟧", "Recupera $N1 ⟦Stolen Blasting Powder=Polvere Esplosiva Rubata⟧ dai trogg a est della ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧, poi torna dal maestro della cava Thesten.", "Questo barile conteneva abbastanza polvere da trasformare la sala del trono di re Magni in un cortile a cielo aperto. Dobbiamo recuperarla dai trogg prima che capiscano come accenderla.", "Spero che tu abbia buone notizie per me.", "Questa dovrebbe essere tutta la polvere rubata. Grazie, {class}.\n\nAccetta questa ricompensa e... ti sarei grat<o/a> se non parlassi a nessuno di questo piccolo incidente.", 0x8848eca5, 0x4fe59366, 0xcc857a5c, 0xb50481e8, 0xad0053e0, "....." },
  [95216] = { "La nuova piaga", "Preleva il ⟦Highly Toxic Strain=Ceppo Altamente Tossico⟧ da Witherfang nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ per Theodore Griffs, a ⟦Undercity=Sepulcra⟧.", "Benvenut<o/a> nell'organo più vitale di ⟦Undercity=Sepulcra⟧: l'Apothecarium! Qui sperimentiamo sui più virulenti tra gli esemplari esotici di Azeroth.\n\nSono di buon umore, perciò ti metterò a parte della mia ultima indagine. Pare che un artropode particolarmente velenoso si aggiri tra le rovine sopra la nostra bella città. Si dice che le sue tossine corrodano persino la carne dei non morti. Che cosa elettrizzante!\n\nVoglio verificare queste voci. Se dovessi trovarti a deperire per il suo morso, mi piacerebbe tanto averne un campione.", "Qualunque sciocco ti dirà che il metodo di trasmissione più efficace passerà sempre per il sangue.\n\nDevo vedere questo ceppo con i miei occhi!", "L'hai ucciso??\n\nHmpf. Per tua fortuna, questo icore dovrebbe bastare per ricostruirne le proprietà. Non ti conviene metterti contro la Royal Apothecary Society.\n\nSparisci dalla mia vista!", 0xbf7a7e24, 0xec263960, 0x9214d563, 0x5c8c63f0, 0x8f9e0d7b, "....." },
  [95217] = { "Il fabbro della cava", "Raccogli 12 Lingotto di Rame e 4 Toughened Boar Hide e consegnali a Frast Dokner.", "Quindi vuoi imparare il mestiere del fabbro? Forse possiamo aiutarci a vicenda.\n\nIl carico di rifornimenti è in ritardo e mi servono materiali per qualche riparazione all'accampamento. Se mi procuri quello che mi serve, ti insegnerò alcune delle mie tecniche. Ti sembra giusto?", "Non battere la fiacca, {name}. Fare il fabbro non è roba da pigri!", "Sei una persona piena di risorse, {name}.\n\nOra ascoltami bene: non ho intenzione di ripetermi!", 0xcf9ba453, 0x56fdeb4f, 0xd3803ca1, 0x8461c8b8, 0x9e396b99, "....." },
  [95218] = { "Ancora la stessa storia", "Parla con Sefira Fulgeterno.", "La Luce mi ha abbandonato. Uno scopo servito, e ora tutto... svanito...\n\nÈ solo questione di tempo prima che la luce si trasformi in oscurità.\n\nHo combattuto contro i demoni e le forze del Flagello con una ferocia che non sapevo che la Luce potesse generare... eppure sono qui a parlare con te, a provare... beh, non riesco proprio a metterlo in parole. Alcuni ritrovano il proprio scopo dopo una perdita, ma io faccio fatica... Dopotutto, sono solo ciò che sono.\n\nOra, a meno che il comandante non abbia un'ultima chiamata all'azione, attendo ciò che verrà.", nil, nil, 0x9782ad68, 0x6eaf7f00, 0x2dc58b1c, nil, nil, "...mm" },
  [95219] = { "Di porto in porto", "Consegna la Botte di Porto di Polveraccesa a ⟦Mardrack Greenwell=Mardrack Pozzoverde⟧ alla Roccaforte di Piumaluna, a Feralas.", "Ho un altro lavoretto per te, ragazzino. Che ne pensi di viaggiare per il mondo?\n\nQuesto qui è uno dei migliori vini Porto che tu abbia mai visto. Il guaio è che deve fare parecchia strada fino a uno dei miei clienti, fino alla Roccaforte di Piumaluna a Feralas. Quando arrivi ad alberi più alti di qualsiasi altro che tu abbia mai visto, sei nel posto giusto.\n\nUno dei miei l'ha imballato a tenuta d'aria ma non si sa cosa potrebbe farlo esplodere, quindi maneggialo con cura, ok, amico?", nil, nil, 0xd8171350, 0xa90a2a71, 0xf2c5517c, nil, nil, "...mm" },
  [95248] = { "Alla Vetta dell'Eternità", "Recati alla Vetta dell'Eternità e parla con i druidi del villaggio dei sopravvissuti.", "Hai abbattuto così tanti del Flagello che finalmente abbiamo un po' di sicurezza. Per questo siamo grati.\n\nUn'altra cosa. Sappiamo che ci sono druidi alla sommità. Proteggono il grande albero e il pozzo.\n\nPerché non ci hanno mai aiutato?\n\nSiamo qui da cinque anni! Perché non hanno mai mandato nemmeno un messaggio a qualcuno su di noi? Far sapere a qualcuno che siamo ancora qui, che siamo ancora vivi!", nil, nil, 0xb966c23b, 0xc3763a22, 0x1a9122d1, nil, nil, "...mm" },
  [95250] = { "Creature abominevoli", "Recupera la ⟦Head of the Baron=Testa del Barone⟧ nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ e riportala al capitano Truman.", "Che vuoi, {race}? Non vedi che c'è una guerra da vincere?\n\nIl mio padrone si è già lanciato nella mischia e mi ha ordinato di restare al mio posto. Però è passato parecchio tempo.\n\nDubito che sopravvivresti dieci minuti in combattimento, ma se serve a tenere occupata la tua mente semplice, perché non vai a cercare il gran maresciallo? È l'eroe più alto e statuario su cui tu abbia mai posato gli occhi. Lo riconoscerai quando lo vedrai.", "Che bello vederti ancora in piedi! Come procede la battaglia? Hai visto il mio signore?", "<Truman guarda la testa del suo ex signore con orrore e disgusto.>\n\nÈ... uno scherzo? Perché mi porti la testa di questa mostruosità?\n\nVattene dalla mia vista! Avrei dovuto sapere di non fidarmi di qualcuno che si allea con la feccia come te. I veri figli di Lordaeron riconquisteranno la nostra casa. E quando lo faremo saremo finalmente liberi di purgarla dalle bestie e da chi come te si accompagna a esse!", 0x83266151, 0xb8e0ac06, 0x0f67af09, 0xdb40bcb8, 0x73ca2063, "....." },
  [95254] = { "RICERCATO: Chelatrappola", "Porta la ⟦Trapclaw's Pincer=Pinza di Chelatrappola⟧ a ⟦Fimbo Greasemitz=Fimbo Manunta⟧.", "Avviso a tutti i pescatori!\n\nCerco carne di granchio. E non i soliti brandelli: parlo di una chela intera. Ho visto un granchio enorme che si aggira sotto i moli, ruba le esche e taglia le lenze.\n\nPagherò una ricompensa a chiunque mi porti la pinza di quella bestia. Avrà anche una porzione del piatto che ci preparerò.\n\n-- ⟦Fimbo Greasemitz=Fimbo Manunta⟧", "Che notizie, {race}?", "L'hai strappata proprio a quella cosa, eh? Impressionante! Con un po' di burro e un pizzico del mio mix segreto di spezie, ci aspetta un gran pranzo!", 0x7381e71b, 0x0715343f, 0x71e25cae, 0xa06629f3, 0x27bb3fea, "....." },
  [95260] = { "Terrori dalle profondità", "Trova al Porto Polveraccesa qualcuno che sappia identificare il mostro dalla pelle dipinta.", "La pelle è dipinta con ampie pennellate di interiora di pesce e inchiostro di calamaro. Sembra raffigurare una sorta di mostro marino, che emerge dalle onde, con un lungo collo. Che creatura sarà?\n\nIl porto più vicino è il Porto Polveraccesa. Se questo mostro esiste davvero e si aggira in queste acque, un marinaio di lì l'avrà sicuramente visto.", nil, "Mostro marino...? Aspetta! Quindi l'hai <hic> visto anche tu!?", 0xc41fb262, 0x788e0d2d, 0xeaff074d, nil, 0xef8f7e17, "...m." },
  [95261] = { "Ci vuole fegato", "Raccogli $N1 Interiora di Bestia e $N2 Fungo Carnemarcia per Argo Fischiasale.", "Quel mostro... con il collo lungo, proprio come hai detto. L'ho visto intorno a quelle isole, fuori con la mia barca. Ho provato <hic> a dirlo alla gente, ma ooh no, non si può <hic> credere al vecchio Argo. È solo un... un... pescatore ubriacone! Che si inventa storie!\n\nGli faremo vedere noi... appena avrò un po' di esca...\n\nEhi! Smettila di startene lì! Mi serviranno interiora, un SACCO. Di qualsiasi bestia da queste parti. Più puzzano <hic> meglio è. Mi serviranno anche dei funghi Carnemarcia. Crescono in quella grotta vicino a Casavento.", nil, nil, 0x7e4cdee7, 0x6b5ebde3, 0x374f563e, nil, nil, "...mm" },
  [95262] = { "La prigione segreta", "Entra nella Prigione di Alcaz e scopri che fine ha fatto il re di ⟦Stormwind=Roccavento⟧.", "Non posso dire di aver mai pensato granché ad Alcaz. Per quanto ne so, è un avamposto abbandonato della terza guerra, di poca importanza. Non ho mai sentito parlare di una prigione là.\n\nBeh, non c'è altra scelta: dobbiamo farti entrare lì per vedere cosa riesci a scoprire, specialmente se c'è la possibilità che il re sia lì.", nil, "<Il re è morto. Le implicazioni di questa notizia continuano ad affondare mentre fatichi a elaborare le informazioni.\n\nSembra anche che ci sia una forza più grande a tirare i fili rispetto al drago minore che hai appena ucciso.\n\nÈ ora di andare a informare Sully di ciò che hai appreso.>", 0xbb8a4a99, 0x2704e85f, 0x75fcd0f4, nil, 0x66757469, "...m." },
  [95263] = { "Notizie funeste", "Torna da Sully McCleary ad ⟦Dustwallow Marsh=Acquemorte⟧.", "<Il re è morto, ucciso in un tentativo di fuga poco prima dell'attacco dei Naga. È una notizia devastante che scuoterà ⟦Stormwind=Roccavento⟧ fin nelle fondamenta. Devi tornare da Sully e dirgli ciò che hai scoperto il più in fretta possibile.>", nil, "<Consegni a Sully il biglietto e la sua espressione si incupisce mentre lo legge.>\n\nGrazie, {class}. È una notizia terribile.", 0xd2cd2d91, 0x6855aaf9, 0x2435dc36, nil, 0xcc03f368, "...m." },
  [95264] = { "Shaw deve saperlo", "Porta la notizia a Matthias Shaw a ⟦Stormwind=Roccavento⟧.", "Shaw deve saperlo il prima possibile. Torna a ⟦Stormwind=Roccavento⟧ e porta la notizia. Ti prego, ti supplico, non dirlo a nessun altro. Potrebbe essere un disastro per ⟦Stormwind=Roccavento⟧ e va gestito con delicatezza.", nil, "<Shaw legge le parole sulla pagina, ma lascia trasparire poca emozione.>\n\nVedo... Grazie per avermi portato queste informazioni. Da qui in poi me ne occupo io, {class}.\n\nDevo insistere con forza che tu lo tenga per te. Se la voce si diffonde prima che siamo pronti, non andrà bene per la gente di ⟦Stormwind=Roccavento⟧.\n\nPer quanto sia pessima questa notizia, hai fatto una cosa enorme per ⟦Stormwind=Roccavento⟧ e non sarà dimenticata. Ecco... ti prego, accetta questo come piccolo segno della gratitudine dell'IR:7 per il tuo servizio.", 0x9fc8717f, 0x7a331bfd, 0xa28181bf, nil, 0xdf0c525b, "...m." },
  [95267] = { "Il ⟦Monster=Mostro⟧ emerge", "Usa la Palla d'Esca Gigante per attirare il mostro marino. Poi porta la sua testa ad Argo Fischiasale.", "L'ultima parte è <hic> facile... prendi quella grossa palla di interiora, eee buttala in acqua! Ehm... non qui però... sarebbe un disastro.\n\nVai a quelle isole <hic> dei murloc, dove hai trovato il disegno. Cerca relitti freschi nell'acqua. Lì devi lanciare l'esca.\n\nAppena quella cosa tira fuori la testa, tagliagliela! Ne faremo una decorazione... per la barca!", nil, nil, 0xb7adbfe6, 0x54805005, 0xb146a9e4, nil, nil, "...mm" },
  [95273] = { "Acqua di Hyjal", "Versa il Ricostituente Purificante dei Pelledura fornito da Fennar Chiomamuschio nell'acqua in fondo alla Tana Legnomorto.", "Ora che sappiamo che i Legnomorto non inquinano l'acqua con la loro sola presenza, possiamo prendere questo campione e lanciare le nostre protezioni con buona volontà. Abbiamo sentito che nella loro tana c'è una pozza delle lacrime della montagna.\n\nViaggia con forza e versa quest'acqua nella pozza nel profondo della Tana Legnomorto.\n\nTorna da noi quando avrai scoperto quali segreti custodiscono le oscure profondità.", nil, nil, 0x62b45624, 0x76377c54, 0x6d869abf, nil, nil, "...mm" },
  [95278] = { "È giunto il momento, fratello...", "Consegna il messaggio a Krom'rosh a Rog'mar.", "La minaccia è più grande di quanto pensassimo. Rog'mar deve essere avvisato.\n\nNon fermarti per nessuno lungo il tuo cammino.", nil, nil, 0x2c53ebce, 0x5ad20d00, 0x7da3e820, nil, nil, "...mm" },
  [95283] = { "I Kor'kron scomparsi", "Parla con Nazeer Puntarossa a ⟦Brackenwall Village=Felcimura⟧.", "Lok-tar, {name}. Mi trovo ad aver bisogno di assistenza per una questione seria.\n\nTempo fa abbiamo inviato un contingente di ⟦Kor'kron Elite=Élite Kor'kron⟧ ad ⟦Dustwallow Marsh=Acquemorte⟧ per una missione speciale. Il problema è che siamo ben oltre la data prevista per il loro rapporto e non abbiamo avuto notizie.\n\nVai a ⟦Brackenwall Village=Felcimura⟧, ad ⟦Dustwallow Marsh=Acquemorte⟧, e parla con un orco di nome Nazeer Puntarossa. Nessuno è più informato di lui sulla situazione di ⟦Dustwallow Marsh=Acquemorte⟧. Scopri ciò che puoi.", nil, nil, 0x79ebb1f3, 0xd42a8ffb, 0x08b7c4cc, nil, nil, "...mm" },
  [95284] = { "L'élite dell'élite", "Trova gli Élite Kor'kron dispersi.", "Un piccolo gruppo di soldati Kor'kron è passato di qui qualche giorno fa. Non mi hanno detto perché fossero qui e io non l'ho chiesto. Hanno comprato provviste, si sono riposati un po' e poi sono ripartiti.\n\nI Kor'kron sono l'élite dell'élite e più duri degli zoccoli di un elekk, ma non riesco a togliermi la sensazione che sia andato storto qualcosa.\n\nHo sentito per caso uno di loro menzionare \"l'isola\", e c'è un'isola chiamata Alcaz proprio al largo della costa. È un posto davvero brutto. Trova qualche amico e scopri cosa è successo a questi Kor'kron.", nil, nil, 0xda025daf, 0x166d3c14, 0xe3a91288, nil, nil, "...mm" },
  [95285] = { "Posto giusto, momento sbagliato", "Parla con il sergente Ulka per saperne di più sulla situazione sull'Isola di Alcaz.", "<Il sergente Ulka si sforza di mettersi a sedere per parlarti. Le porgi la mano per aiutarla, ma lei si limita a scacciarla con un manrovescio.>\n\nVa bene recluta... mettiamoti al corrente.", nil, nil, 0xed0bfcb2, 0x83c59f12, 0x309b360b, nil, nil, "...mm" },
  [95288] = { "Il paradiso dei contrabbandieri", "Raccogli $N1 Beni di Contrabbando per Friz Sfrigolascintilla al Porto Polveraccesa.", "Hai l'aria di uno che fa sempre quello che gli dicono gli altri. Mi piace, in un tirapiedi. Con un po' di addestramento potresti diventare una grande risorsa. Mettiamolo alla prova.\n\nDi recente alcuni di quei pirati del Mare d'Oriente se la sono svignata con un carico della MIA merce rubata. È poco sportivo. L'ho rubata io per prima!\n\nLezione uno, tirapiedi. Mai pugnalare alle spalle un pugnalatore alle spalle. Vai a mostrare loro che hanno scherzato con il goblin sbagliato e riprenditi la mia roba. Con la forza, preferibilmente.", "Come va l'addestramento? Si tratta solo di tagliare qualche gola. Ho grandi speranze per te, <ragazzo/ragazza>.", "Pare che tu abbia imparato bene la tua prima lezione, tirapiedi. E non ti faccio nemmeno pagare per questa pepita di saggezza! Non sono un gran capo o cosa?\n\nPrenditi un po' di tempo per riflettere su questa illuminazione, poi si passa al prossimo incarico.", 0xacce94e6, 0x0ef2467a, 0x34e26573, 0xcb4c960b, 0x601de9cd, "....." },
  [95293] = { "La specialità del contrabbandiere", "Consegna La Specialità di Friz al capitano Monetastorta alla Costa Vento di Levante.", "Quella merce che hai recuperato dai pirati del Mare d'Oriente doveva essere spedita direttamente a me. Ciò significa che il vecchio Monetastorta pensa di potersi infilare nel mio territorio. Pare che voglia scatenare una guerra commerciale. Noi, però, siamo gente civile.\n\nLezione due, tirapiedi. Non dobbiamo abbassarci al loro livello. Prendi questa cassa che ho preparato apposta per il buon capitano. Lo trovi sulla sua nave lungo la Costa Vento di Levante. Si merita un premio per le sue astute tattiche di negoziazione.", "Ringrazia la tua fortuna se non ti spacco da prua a poppa per aver messo piede sulla mia nave, marinaio d'acqua dolce! Dammi una buona ragione per non farti passare sotto la chiglia, subito!", "Un regalo da Friz? Deve sapere quando è battuta, harharhar!\n\nChe cos'è quel ticchettio...?", 0xb7c0cc5c, 0x09eb355f, 0xf241038e, 0xe2bdaf85, 0xb5ec8302, "....." },
  [95294] = { "L'affare del contrabbandiere", "Torna da Friz Sfrigolascintilla al Porto Polveraccesa.", "Friz sa proprio come farsi capire. Beh, da parte mia non sentirai obiezioni. I pirati del Mare d'Oriente non interferiranno con i suoi affari. In cambio, forse possiamo trovare un accordo. Fare i pirati è un po' difficile quando una goblin offesa ti manda dietro avventurieri predoni tutto il giorno.\n\nTorna di corsa dal tuo padrone, {class}. Fai sapere a Friz che c'è un nuovo capitano al comando e che prevede un futuro proficuo tra noi.", nil, "Capitano chi? Be', chiunque sia, sembra che voi due abbiate imparato la mia prossima lezione importante.\n\nNon provate mai a fregarmi.", 0xdfdbe23f, 0xc86a92fb, 0xf74a396c, nil, 0x9d3b04f6, "...m." },
  [95295] = { "Conosco un tizio", "Parla con il contatto di Friz a ⟦Booty Bay=Baia del Bottino⟧.", "Hai fatto un buon lavoro con quei pirati, tirapiedi. Ma ecco una lezione che potresti voler ricordare. Quelli che alcuni chiamano pirati, altri li chiamano filibustieri. E chi dice filibustiere dice bottino gratis. E non c'è posto migliore per il bottino gratis della ⟦Booty Bay=Baia del Bottino⟧!\n\n<Friz aspetta la tua risposta.>\n\nSeguimi, ragazzo. Sto dicendo che devi andare alla ⟦Booty Bay=Baia del Bottino⟧ a incontrare il mio contatto. Prende merci dai pirati del posto... ehm, filibustieri. Insomma, vai a cercare Ruzzgot. Ti spiegherà il resto.", nil, nil, 0x21e479e5, 0xe3d0d2e8, 0x81b82ccb, nil, nil, "...mm" },
  [95296] = { "Spedizione e imballaggio", "Parla con il capitano del porto Frizzavapore al ⟦Steamwheedle Port=Porto degli Spargifumo⟧, a Tanaris.", "Sembra che tu sia pronto per la prossima lezione, campione. Ho delle trattative mie da fare qui in città, quindi mi serve che tu sbrighi un paio di commissioni per me mentre sono impegnata.\n\nTutto ciò che devi fare è prendere la prossima nave vicino ai moli e consegnare questa cassa al mio socio al ⟦Steamwheedle Port=Porto degli Spargifumo⟧.\n\nNon guardarmi così. Sarà parecchio emozionante, ne sono certa. Far pagare un goblin è molto più difficile che malmenare la feccia locale, per non parlare di passare la dogana. Ti inventerai qualcosa.", nil, nil, 0x2df4f691, 0xf45e87c6, 0xaf23f96a, nil, nil, "...mm" },
  [95309] = { "Nessun orco lasciato indietro", "Entra nella Prigione di Alcaz e trova il comandante Folkar.", "I tuoi ordini sono semplici: scendi nelle segrete sotto il forte e trova il comandante Folkar. Liberalo, se è vivo, e scopri tutto quello che puoi su cosa diamine sta succedendo qui.\n\nLà sotto c'è un esercito che ti aspetta e non sopravviverai da solo. Spero tu abbia degli alleati... possibilmente forti.", nil, nil, 0x14fa1c97, 0x98b28740, 0x5ed3381c, nil, nil, "...mm" },
  [95312] = { "Siamo venuti a riscuotere", "Parla con Fizbuz Mithril a ⟦Gadgetzan=Meccania⟧.", "Io non ho i soldi di Friz. Beh, li avevo, ma li ho scommessi tutti sul vecchio Mascellumaca qui nell'arena di Fizbuz a ⟦Gadgetzan=Meccania⟧.\n\nNon guardarmi così. Era un investimento solido. Ho vinto alla grande! Solo che non ho ancora avuto modo di riscuotere la vincita. Se sei il nuovo <galoppino/galoppina> di Friz, perché non vai a prenderla per me? Ho la schiena rovinata, sai.\n\nEhi, non vorrai tornare dal tuo capo a mani vuote, vero? ⟦Gadgetzan=Meccania⟧ è subito a ovest di qui. Non puoi sbagliare.", nil, nil, 0x1b965496, 0xf77b0d34, 0xd1b29959, nil, nil, "...mm", nil, nil, 0xa59e9499, nil, nil },
  [95314] = { "Quell'elisir verde di ⟦Shadowvale=Valle Ombrosa⟧", "Raccogli $N1 ⟦Bottles of Whispering Elixir=Bottiglie di Elisir Sussurrante⟧ a ⟦Shadowvale=Valle Ombrosa⟧, poi torna da Carolai Anise a Brill.", "Prima dell'invasione del Flagello, l'isolato villaggio di ⟦Shadowvale=Valle Ombrosa⟧ era noto per il suo ⟦Whispering Elixir=Elisir Sussurrante⟧. Distillato da erbe che si trovano solo a ⟦Tyr's Fall=Caduta di Tyr⟧, l'elisir era ricercato da speziali, mistici e avvelenatori, anche dopo essere stato bandito in città.\n\nHo ricevuto richieste da diversi compratori ansiosi di mettere le mani su un po' di elisir. Raggiungi le rovine di ⟦Shadowvale=Valle Ombrosa⟧, nel profondo della ⟦Whispering Forest=Foresta Sussurrante⟧, a ovest. Offro un compenso considerevole se riesci a recuperarne qualche bottiglia per me.", "Confido che tu non ti sia pers<o/a>?", "Dici che a ⟦Shadowvale=Valle Ombrosa⟧ c'è del male? Ammetto che non mi sorprende. La gente della foresta era un tipo strano e non amava i visitatori. Alcuni credono che la ⟦Whispering Forest=Foresta Sussurrante⟧ stessa sia maledetta e che l'elisir distillato dalle sue radici porti con sé la stessa maledizione...\n\n...ma basta con superstizioni e dicerie, {name}. Grazie per gli elisir. Ecco, prendi questo come pagamento.", 0x62c6b7bf, 0xff6777a1, 0x5740e013, 0x46ba8900, 0x23664c51, "....." },
  [95315] = { "Il rapporto delle Radure del Fiume", "Consegna la Corrispondenza del ⟦Captain Nials=Capitano Nials⟧ a Demar Brant a Forte Farholde, lungo la costa sudorientale delle Radure del Fiume.", "Un nostro esploratore riferisce che una grande forza nemica si sta ammassando molto, molto a sud, ben oltre le ⟦Wetlands=Paludi Grigie⟧.\n\nCosa ancora più curiosa, sembra esserci laggiù un insediamento dell'Alleanza. Farholde? Il nome suona familiare.\n\nNon aspettiamo. Meglio aprire il dialogo prima che sia troppo tardi. Abbiamo già abbastanza problemi qui.\n\nPrendi questa corrispondenza e consegnala a chi dice di essere il capo di questo distaccamento.", nil, nil, 0x1f867d7e, 0xa6c18e24, 0xa43e17f1, nil, nil, "...mm" },
  [95316] = { "Il metodo sperimentale", "Usa le pigne per distruggere le postazioni di lavoro del Regno delle Ceneri.", "D'accordo, terricolo, avrai notato che la combinazione di pigne e melma intrisa di energia vile è davvero disgustosa, se vuoi la mia opinione. È però anche molto pericolosa... ed è proprio ciò che ci serve!\n\nPrendi queste pigne e raggiungi con cautela, ripeto, con cautela, il vicino accampamento degli stregoni. Una volta lì, usa questi oggetti per seminare il caos sulle loro preziose postazioni di lavoro.\n\nSono certa che i risultati saranno divertenti da vedere di persona! Questo dovrebbe sicuramente rallentarli.", nil, nil, 0x33413196, 0x3096ec86, 0x92cd1d10, nil, nil, "...mm" },
  [95317] = { "Appunti, appunti, appunti", "Trova $N1 Appunti sugli Esperimenti con la Vilcenere.", "Ascolta, {class}. Ci sono stati dei visitatori parecchio rumorosi poco più su, sulla montagna. Stanno contaminando la terra con la loro magia demoniaca e sperimentano con cumuli di cenere. È ora di indagare.\n\nQuando dico \"noi\", intendo tu.\n\nVoglio che ti guardi intorno e indaghi sul loro accampamento! Vedi se riesci a portarmi degli appunti su cosa stanno combinando i nostri misteriosi \"amici\" vili. Con ego così grandi hanno di sicuro scritto qualcosa che possiamo sfruttare. Magari li portano addosso?", nil, nil, 0x9be3d5e9, 0x2d1fefc7, 0x9588db7d, nil, nil, "...mm" },
  [95318] = { "Assaggio di cenere", "Uccidi $N1 Accolito delle Ceneri.", "Quindi, per sconvolgere davvero le operazioni qui e farmi uscire da questa gabbia, dovremo uccidere quattro mortali molto potenti. Questa gabbia ha delle protezioni demoniache che non verranno dissolte finché tutti e quattro non saranno morti, e quella chiave non può essere usata finché le protezioni non cadono.\n\nSenti, mi sembri <un/una> {race} che sa cavarsela, ma ho bisogno di qualche prova in più che tu riesca davvero ad affrontare questi stupidi stregoni prima di darti informazioni utili.\n\nTanto per cominciare, come uccidere una marea di questi stregoni. Facile, no?", nil, nil, 0x9d217f21, 0x92a0dfab, 0x3d0ca09e, nil, nil, "...mm" },
  [95319] = { "Collezione cristallina", "Raccogli $N1 Cristallo di Vilmelma e $N2 Cristallo di Vilmelma Intatto.", "Ascolta, so che puoi sentire l'odore delle pozze di sangue vile dietro di me e sono certo che hai visto i cristalli che ne crescono. Questi cristalli hanno proprietà speciali dovute alle ceneri di Archimonde che piovono su questo lato della collina.\n\nQualcosa nel modo in cui si formano li rende particolarmente efficaci nel drenare le energie vili, il che è un grosso problema per uno come me, ma possono comunque avere i loro usi.\n\nVoglio che tu ne raccolga un po' per me. Prova a prenderne di vari tipi. Capirò cosa mi serve quando lo vedrò.", nil, nil, 0x98a88f50, 0x5e6a7e62, 0x29105417, nil, nil, "...mm" },
  [95320] = { "Una domanda curiosa", "Trova il demone imprigionato.", "C'è un demone in gabbia poco più avanti lungo la strada, vicino all'ingresso dell'accampamento degli incantatori demoniaci, che sta facendo un gran baccano.\n\nContinua a straparlare di prigionia e libertà. Qualcosa su ossa che bruciano e vendetta?\n\n<Il corvo si sporge verso di te con uno sguardo malizioso. Come per sottolineare, fa dondolare una chiave di ferro con uno degli artigli.>\n\nVediamo se riusciamo a stringere un accordo con il nostro piccolo \"amico\" e a scoprire cosa sa di questi brutti incantatori demoniaci.", nil, nil, 0x6de5d72d, 0x18655d9b, 0x6219cbc9, nil, nil, "...mm" },
  [95321] = { "Il dovuto di Tazzik", "Affronta Tazzik al ⟦Steamwheedle Port=Porto degli Spargifumo⟧, a Tanaris.", "Tazzik ti ha mandato a riscuotere le sue vincite? Dev'essere uno scherzo, vero? Il suo campione dalla mascella molle non è durato nemmeno due minuti nell'arena! Quel perdente non ha guadagnato nemmeno un rame.\n\nNon sono affari miei, amico, ma se fossi in te me la darei a gambe verso il ⟦Steamwheedle Port=Porto degli Spargifumo⟧. Mentre sei qui a parlare con me, quel topastro di Tazzik sta probabilmente cercando di saltare sulla prossima nave in partenza.", nil, nil, 0x12009d0a, 0x04d46b31, 0x397dba38, nil, nil, "...mm" },
  [95322] = { "Recupero della merce", "Trova il Baule dei Velerosse fuori da ⟦Booty Bay=Baia del Bottino⟧, nella Valle di Rovotorto.", "Tempismo perfetto, amico. Stavo giusto andando a ritirare il mio carico dai ⟦Bloodsail Buccaneers=Bucanieri Velerosse⟧. Sono ottimi amici miei. Sempre felici di fornire tutto ciò per cui Friz è disposta a pagare.\n\nMa, ehm, per ogni evenienza, non guasta che tu faccia da mio collegamento. Un bravo carovaniere sa che non guasta mostrare un po' di muscoli. Solo come deterrente, ovviamente.\n\nHanno detto di aver lasciato la mia roba in un forziere sulla collina fuori città, per tenerla al sicuro. Perché non dai un'occhiata per me, eh?", nil, nil, 0x8965a245, 0x62b03729, 0xc4d885aa, nil, nil, "...mm" },
  [95325] = { "Ci hanno derubati!", "Trova il ⟦Venture Co. Ledger=Libro Mastro della S.P.R. & Co.⟧ nel Campo della S.P.R. & Co. vicino al Lago Nezferiti, a Rovotorto.", "Ho già speso buoni soldi per quella cassa. Non lasceremo certo che se la tengano!\n\nVuoi la tua spedizione? Vai all'accampamento della S.P.R. & Co. a nord e scopri chi è il responsabile di questo tradimento! Non è più una questione di soldi, {name}. È una questione di giustizia! E forse un po' anche di soldi.", nil, nil, 0xe33ec9a8, 0x58fa8715, 0x15760d4d, nil, nil, "...mm" },
  [95326] = { "La grande rivalsa", "Uccidi l'agente della S.P.R. & Co. e riprendi per lui il Carico di Ruzzgot a ⟦Booty Bay=Baia del Bottino⟧.", "<Il registro contiene un elenco di ogni consegna di Ruzzgot. L'ultima nota segna il colpo come riuscito e gli oggetti di valore di Ruzzgot ritirati da un vicino agente della S.P.R. & Co. La merce dev'essere ancora con lui.>", nil, nil, 0x9446396d, 0x1705fc92, 0xdd2746be, nil, nil, "...mm" },
  [95327] = { "Tutto è bene quel che finisce bene", "Torna da Friz Sfrigolascintilla al Porto Polveraccesa, nelle Radure del Fiume.", "Pare che un patto sia un patto. La S.P.R. & Co. ha avuto ciò che si meritava, Friz riceve il suo bottino e tutti sono contenti. Nel complesso una transazione piuttosto liscia, se posso dirlo.\n\nOra sparisci, a breve mi arriva un altro carico da dei Pirati dei Mari del Sud.", nil, nil, 0xa82e7590, 0x04ad02a4, 0x694d1d68, nil, nil, "...mm" },
  [95328] = { "⟦Whispering Horror Residue=Residuo di Orrore Sussurrante⟧", "Consegna Whispering Horror Residue a padre Niflheim, nel ⟦War Quarter=Quartiere della Guerra⟧ di ⟦Undercity=Sepulcra⟧.", "Contro ogni buonsenso, raschi via e raccogli i resti ancora contorti della bestia. Qualcuno a ⟦Undercity=Sepulcra⟧ potrebbe trovarli utili.", "Hai qualcosa per me, {class}?", "Che esemplare interessante. Da sotto la Foresta Sussurrante, dici? Non è un segreto che quel luogo maledetto sia toccato dal Vuoto.\n\nAccolgo con piacere l'opportunità di esplorare i misteri dell'ombra, {class}. Permettimi di offrirti un pagamento per ciò che hai trovato.", 0xb283ff1d, 0xa13a9b4c, 0x1336682a, 0xcbd58f92, 0xa810ae88, "....." },
  [95329] = { "Sul campo", "Vai al Presidio di Terral per ricevere un rapporto sulla situazione dal guardiano Cornelius.", "C'è una torre di guardia che domina le pianure a nord. Serve da punto di osservazione per tracciare qualsiasi movimento delle forze dell'Orda.\n\nIl guardiano di stanza lì si chiama Cornelius. Parlagli e fatti dare un rapporto sulla situazione. È tutto solo là fuori, quindi mi piace controllarlo con una certa regolarità. Ti avverto, può essere un po'... taciturno. È per questo che l'hanno assegnato a un posto così remoto, in primo luogo.", nil, "Il mio stato? Non c'è molto da riferire. Le pianure brulicano di orchi, come sempre, e l'unico aiuto che Demar sembra interessato a mandarmi sono novellini come te.", 0xa2ea5c69, 0x73c32093, 0xf5a044e1, nil, 0x16959fb0, "...m." },
  [95330] = { "Ama il prossimo tuo", "Consegna le eccedenze di prodotti agricoli di Cassandra a Halligan Turner al Campo di Disboscamento di Turner.", "Io e mio marito abbiamo una fattoria a nord di qui. Vengo a Farholde dopo ogni raccolto per vendere ciò che coltiviamo. Nelle buone stagioni mi piace mettere da parte ciò che non vendiamo per darlo a chi ha bisogno di un po' di sollievo. Bisogna prendersi cura dei vicini, dico io.\n\nA nord della nostra fattoria c'è un accampamento di taglialegna, proprio sul fiume. Sono certa che a quei ragazzi farebbero comodo un po' di frutta e verdura per variare la dieta.\n\nSe passi di là, potresti consegnare questo al caposquadra? Si chiama Halligan Turner.", "Mi sa che hai una consegna per me.", "I Wheeler sono troppo gentili!\n\nCassandra ha ragione, quaggiù non mangiamo granché oltre a carne e pane. Mi assicurerò che tutti ne ricevano una parte.\n\nGrazie per il regalo. Dovrò ricambiare la sua gentilezza prima o poi.", 0xe903ac7d, 0xb9db9a6f, 0x2a1e469d, 0x08b61e06, 0xb639098b, "....." },
  [95331] = { nil, nil, nil, nil, nil, 0x33acc140, nil, nil, nil, nil, "emmmm" },
  [95349] = { "Il Circolo della Terra", "Prendi la nave skycutter dall'⟦Zephras Isle=Isola di Zephras⟧ a Mulgore e, all'arrivo, parla con Alaana Stormwalker.", "I recenti eventi legati al culto hanno ritardato i miei piani di viaggio verso Azeroth, e per un po' devo restare qui a Valanaar. Tu e una manciata di altri Windshaper sarete invece la nostra avanguardia. Alaana Stormwalker accoglierà i nostri Windshaper al loro arrivo a Mulgore, e ti invito a esplorare Azeroth mentre noi concludiamo i nostri affari qui. Presto vi raggiungeremo.\n\nQuando sarai pront<o/a>, raggiungi il molo appena fuori da questa loggia e sali sulla nave skycutter che troverai lì.\n\nBanu-Alah, {name}.", nil, "Altri avventurieri da Zephras, vedo. Magnifico. I venti sono davvero dalla nostra parte! Ci vorrà un po' di tempo per stabilirci qui, quindi potresti approfittarne per esplorare questa nuova terra.\n\nAzeroth è un mondo nuovo ed emozionante, ma è anche un mondo pericoloso. Faresti bene a prepararti a questa nuova avventura conoscendo le terre qui vicino.", 0x28da0b16, 0x74e6dafa, 0x76858aa9, nil, 0xde8ad8f1, "...m." },
  [95350] = { "Benvenuti su Azeroth", "Raggiungi Orgrimmar e parla con Thrall nella Valle della Saggezza.", "Quaggiù il mondo è grande, e i nostri nuovi alleati sono la chiave della nostra sopravvivenza.\n\nIl Circolo della Terra fa parte dell'\"⟦Horde=Orda⟧\", una fiera unione di popoli affini. La vicina città di ⟦Thunder Bluff=Picco del Tuono⟧ appartiene all'⟦Horde=Orda⟧, e più a est si trova la capitale, Orgrimmar.\n\nCerca il maestro di volo al centro di ⟦Thunder Bluff=Picco del Tuono⟧. Ti porterà in volo a Orgrimmar, dove prenderai contatto con il Capoguerra dell'⟦Horde=Orda⟧, Thrall, a nome dei Windshaper. Che i venti ti guidino, {name}.", nil, "Lok-tar, {class}. Sono Thrall, Capoguerra dell'⟦Horde=Orda⟧.\n\nUn messaggero del Circolo della Terra mi ha detto di aspettarmi dei membri dei Windshaper, ed eccoti qui. Non mi sarei aspettato di trovarmi davanti uno degli alti elfi, qui a Orgrimmar, ma l'⟦Horde=Orda⟧ ti accoglierà comunque come suo ospite.\n\nHai la mia benedizione per viaggiare attraverso le terre dell'⟦Horde=Orda⟧. Va' con onore, Windshaper.", 0x2f003d6f, 0x53ee86b6, 0x7024f167, nil, 0x328b0c81, "...m." },
  [95378] = { "La testa dell'Idra", "Recupera le ossa di Frezzlie Scoppiafrizz, Tyaeha Giuroscuro e Dazka Sonnombroso.", "È ora di tagliare le teste di questa idra, se capisci cosa intendo.\n\nCi sono tre capi che vanno uccisi per rallentare le operazioni qui. Convenientemente, vanno uccisi anche per rimuovere le protezioni sulla mia gabbia.\n\nTyaeha si trova nella casa delle malattie, vicino all'albero inquietante. Dazka è nel reparto degli alchimisti, con tutte le pozioni, e quello sciocco di Frezzlie è senza dubbio accanto alle fosse di melma lungo il crinale settentrionale dell'accampamento.\n\nVai a ucciderli e portami le loro ossa!", nil, nil, 0xfd37973a, 0x21eac604, 0xa93f76b5, nil, nil, "...mm" },
  [95379] = { "Una vendetta così dolce", "Uccidi Brashann Tetrabuio e cerca la sua pietra dell'anima sul suo corpo.", "Brashann Tetrabuio, Maestro dei Vasi.\n\n<Il volto di Felflick si contrae in un ringhio.>\n\nFu lui a sottomettermi alla sommità. LUI è il motivo per cui sono qui, in primo luogo.\n\nIl suo lavoro con questi cristalli di cenere vile è la spina dorsale di questa operazione. Ha sperimentato in modo ossessivo l'ancoraggio di anime in questi cristalli e il suo lavoro non è passato inosservato a quei viscidi Spinanera.\n\nUsa questo cristallo intatto per drenare il suo potere, poi mettigli fine e portami la sua pietra dell'anima.", nil, nil, 0xc072e31b, 0xf37d46c1, 0x5a9e4913, nil, nil, "...mm" },
  [95380] = { "Una fonte prolifica", "Raccogli $N1 Melma di Vilmelma.", "Ascolta bene, {class}. Sembra che siamo in una situazione piuttosto appiccicosa. Sapevo che quei maledetti incantatori demoniaci stavano tramando qualcosa di losco, ma è molto peggio di quanto mi aspettassi.\n\nPer fortuna ho un'idea!\n\nPerché funzioni mi servirà della melma vile delle creature di melma che si trovano nelle pozze di sangue vile dietro di me. Non le ossa o i pezzi, solo la melma! Assicurati di pulirti le mani dopo averla maneggiata. Sembra corrosiva.\n\nNiente paura, non ho dubbi che troverai un modo per portarmela.", nil, nil, 0xacfb2cfc, 0xaadbfee5, 0x79c19745, nil, nil, "...mm" },
  [95383] = { "Spedizione e imballaggio", "Consegna la Scorta Segreta di Friz a Tazzik al ⟦Steamwheedle Port=Porto degli Spargifumo⟧.", "<Il capitano del porto Frizzavapore esamina la moneta che gli hai offerto.>\n\nOh-oh! La vecchia Friz sta proprio addestrando bene la nuova generazione. Scusa per il ritardo, <signore/signora>. Sei qui per consegnare una cassa a qualcuno in città, giusto? Non so niente al riguardo, ma se lo sapessi andrei a parlare con Tazzik sul molo. Sembra interessato a cose del genere.\n\nMa fai in fretta, eh? Non voglio che la gente si faccia strane idee, sai.", nil, nil, 0x2df4f691, 0x1421c036, 0x1cb7078c, nil, nil, "...mm", nil, nil, 0xcd83683e, nil, nil },
  [95384] = { "Appunti mistici incompleti", "Porta la pergamena incompleta a Dudd Fizzlescroll, alla ⟦Booty Bay=Baia del Bottino⟧.", "<Gli strani simboli sulla pergamena magica ti confondono. Anche se non conosci la lingua in cui è scritta, non avverti al suo interno forze particolarmente instabili. Forse un collezionista di magie bizzarre saprebbe che farsene.>", nil, "Una strana pergamena, dici? Sì, questa sembra magia di prima qualità. La roba BUONA. Grazie per averla portata qui, <amico/amica>. Prendi questa come ricompensa per il tuo tempo.\n\nOra, vediamo di tradurre questo pasticcio e trascriverlo nei miei archivi...", 0xec99fcec, 0xa76f397b, 0x819e84fc, nil, 0xc248fce0, "...m." },
  [95385] = { "Pergamena Mistica Strappata", "Porta la pergamena parziale a Dudd Raschiarotolo a ⟦Booty Bay=Baia del Bottino⟧.", "<Dal frammento di pergamena emana una debole magia. La lingua ti è sconosciuta, anche se intuisci che non è pericolosa. La maggior parte la riterrebbe inutile, ma potrebbe esserci un collezionista particolare che ne trovi un uso.>", nil, "Una pergamena magica? Che giornata fortunata! Copio solo queste rune sul mio lavoro e avrai un posto in prima fila all'alba di un nuovo leggendario ingegnere. Ma non avvicinarti troppo, non voglio dover pagarti diritti d'autore... voglio dire, non voglio che ti faccia male.", 0x9d05aeb5, 0xa76f397b, 0x1b7d2cfd, nil, 0x5f53510f, "...m." },
  [95417] = { "Quelli viola", "Trova gli ogre dispersi nelle grotte sotto Radura Solare per Ditomazza.", "Ditomazza vede amici andare via. Alcuni non tornano. Alcuni tornano viola. Quello strano. Quelli viola non fanno più come amici.\n\nDove vanno altri? Perché non tornano? Fa pensare Ditomazza.\n\nTu colpisci forte. Forse vai a trovare amici in caverna? Forse diventi viola. Anche quello strano.", nil, nil, 0x494d5db5, 0x07743954, 0xe7ce4f0b, nil, nil, "...mm" },
  [95418] = { "Spargi la voce", "Consegna la testa di Chogg a Tran'gul a Rog'mar.", "Io finito con Crepuscolo. Ditomazza ora ogre libero.\n\nIo vado a trovare Clugfist. Lui ogre più grosso che Ditomazza ha mai visto. Lui lascia Crepuscolo. Porta molti amici con lui. Ora turno di Ditomazza. Io mi unisco a ogre liberi. Loro vanno sulle colline. Ditomazza manca colline. Niente più rompere sassi. Forse tu vieni qualche volta?\n\nIo resto qui finché strada libera. Tu porti teste di Chogg'Zac agli amici. Beh. Forse una testa. Io ne prendo una anche. Scambio giusto.", nil, nil, 0x2e6074fc, 0xc63cec3c, 0xbd25ab1c, nil, nil, "...mm" },
  [95420] = { "La terra dei giganti", "Consegna la testa di Chogg alla città degli ogre a nord.", "Chiaramente questi ogre sbandati non sono amici del ⟦Twilight's Hammer=Martello del Crepuscolo⟧. Noi orchi abbiamo una storia onorevole di lotta al fianco degli ogre e forse è ora di richiamare quelle vecchie alleanze. E questa testa potrebbe essere la chiave.\n\nCi sono state segnalazioni di attività di ogre sulle colline molto a nord. Se questo Ditomazza è attendibile, deve essere lì che questo clan ha la sua casa. Va' alla loro roccaforte e offri questo trofeo come segno della nostra amicizia. Con un po' di fortuna ascolteranno la tua proposta prima di schiacciarti.", nil, nil, 0x6c60d0c4, 0xfa36b640, 0xad996936, nil, nil, "...mm" },
  [95424] = { "Ha ragione il più forte", "Uccidi $N1 Sbranatore del Crepuscolo e $N2 Evocafuoco del Crepuscolo per Clugfist a Bolder'ok.", "Qui ogre apprezzano forza e sangue.\n\nDeboli lasciano Bolder'ok. Tornate a ⟦Twilight's Hammer=Martello del Crepuscolo⟧.\n\nTu non grosso. Forse tu forte. Mostra a Clugfist forza e schiaccia ogre deboli. Se creatura piccola riesce.", nil, nil, 0xcf499072, 0x5fff806e, 0x84414e3b, nil, nil, "...mm" },
  [95425] = { "Campione indegno", "Raccogli Picchiateschi da Klunk per Clugfist a Bolder'ok.", "Klunk una volta campione più grande di Clugfist. Lui forte. Io dare a Klunk arma potente.\n\nMa Clugfist sbaglia. Klunk debole come altri. Lui lascia Bolder'ok. Torna a ⟦Twilight's Hammer=Martello del Crepuscolo⟧. Porta ogre con lui in caverna a est vicino acqua. Porta arma potente con lui!\n\nQuella arma di Clugfist! Spacca testa di Klunk e riprendi Spaccateschi. Lui non campione di nessuno!", nil, nil, 0xdd6c393c, 0xc4de314c, 0xf6b8060f, nil, nil, "...mm" },
  [95426] = { "Rifornimenti di Rog'mar", "Recupera $N1 Carico di Rifornimenti dell'⟦Horde=Orda⟧ dai campi di addestramento a nord di Rog'mar.", "Consegnare rifornimenti in quest'area non è impresa da poco. Ogni genere di individuo senza scrupoli ci circonda da ogni direzione, ognuno in cerca della propria fetta di torta.\n\nDetto questo, forse è un'occasione per rallentare la crescita di Rog'mar. Che ne dici di infilare un po' di bastoni tra le ruote ai piani dei nostri amici orchi?\n\nVai a nord di Rog'mar, ai loro campi d'addestramento, e rubane le spedizioni di rifornimenti. Già solo il tempo di recupero garantisce che le nostre forze restino pronte alla battaglia mentre le loro... beh, vedi dove si va a parare.", "Allora...? Hai avuto fortuna con quei rifornimenti?", "Ottimo lavoro, {name}. Il rifornimento richiederà del tempo--sempre che le loro carovane arrivino qui sane e salve.", 0x94aaff8f, 0x452706fa, 0x019dbe3c, 0x8bbbbbf2, 0x4672b31d, "....." },
  [95427] = { "Mai più Crepuscolo!", "Uccidi Chogg'Zac nella grotta di Radura Solare e raccogli le loro teste per Ditomazza.", "Amici di Ditomazza... morti? Perché?\n\nQuesta colpa di Chogg'Zac! Loro dicono fanno ogre forti. Mentono!!\n\nNiente più rompere sassi! Creatura piccola aiuta Ditomazza a rompere stupide teste di Chogg'zac invece!", nil, nil, 0xdfa3c368, 0x3d4e26c0, 0x7a41956b, nil, nil, "...mm" },
  [95428] = { "Il decreto di Clugfist", "Presentati a Krom'rosh a Rog'mar.", "Piccolo {race} spacca Crepuscolo bene. Forse tua ⟦Horde=Orda⟧ più forte di quanto Clugfist pensava.\n\nTu libero di restare a Bolder'ok. Per ora.\n\nDi' ad altri piccoli che presto versiamo sangue di nuovo.", nil, nil, 0x9805b458, 0x0c4f9d27, 0x296725a3, nil, nil, "...mm" },
  [95431] = { "Brontolii di malcontento", "Cerca l'ogre di Bolder'ok nella grotta vicina.", "Mentre seguivo i movimenti del nostro nemico, ho scoperto una debolezza nei loro ranghi. Dei dissidenti ogre hanno iniziato a ribellarsi, in cerca della stessa libertà dei loro simili di Bolder'ok. La voce delle tue imprese si è diffusa. Dobbiamo sfruttarla.\n\nHo individuato un guerriero di Bolder'ok diretto alle caverne a ovest di qui in cerca dei suoi fratelli e sorelle. Trovalo e unisciti ai suoi sforzi per radunare la sua gente.", nil, nil, 0x07dcda58, 0xc0b3c9f5, 0x6e24eefc, nil, nil, "...mm" },
  [95432] = { "Insorgi!", "Recluta $N1 Minatore Ogre.", "Quando Crag'rog sente che piccolo {race} libera ogre, anche Crag'rog vuole ogre liberi.\n\nCon piccolo {class} qui, noi spacchiamo Crepuscolo insieme. Rompiamo loro ossa. Facciamoli urlare. Ogre liberi! Poi a casa in tempo per stufato.", nil, nil, 0x4d5e50d3, 0x7c66f089, 0x9ba5a852, nil, nil, "...mm" },
  [95433] = { "Morte al boia", "Raccogli la Mazza del Boia dal boia Morg nel Velo del Crepuscolo per Clugfist a Bolder'ok.", "Quando Clugfist lascia Crepuscolo, un ogre si mette in mezzo. Morg.\n\nMorg ogre enorme. Quasi grosso come Clugfist. Ma non il più grosso. Lui ha bisogno di piccoli per proteggerlo. Clugfist mai avuto combattimento leale. Ora NOI non combattiamo leale.\n\nTrova Morg. Porta molti piccoli con te. Uccidilo. Riporta mazza a Clugfist. Così Crepuscolo sa che non ci sfida più!", nil, nil, 0x0019573e, 0x52aaa4fb, 0x8a4b297b, nil, nil, "...mm" },
  [95454] = { "L'onore dei Kor'kron", "Cerca re Varian Wrynn nella Prigione di Alcaz.", "Il mio braccio buono con l'ascia è rotto e la maggior parte della mia élite è morta. L'onore dei Kor'kron ora poggia su di te.\n\nEravamo stati mandati qui per prelevare un prigioniero, ma non un prigioniero qualsiasi... Siamo qui per il re di ⟦Stormwind=Roccavento⟧, Varian Wrynn. Abbiamo intercettato informazioni secondo cui era tenuto qui e il nostro Capoguerra ci ha ordinato di riportarlo a Orgrimmar vivo. La presenza di draghi neri... complica le cose.\n\nHo bisogno che tu prosegua e trovi Wrynn. Ti aspetterò qui mentre lo cerchi.", nil, nil, 0x682af88d, 0x1bea7690, 0x5f8e67b6, nil, nil, "...mm" },
  [95472] = { "Premio di consolazione", "Porta la Camicia Sudata di Tazzik a Friz Sfrigolascintilla al Porto Polveraccesa.", "Ti dico che non posso ripagare Friz! Non mi è rimasto niente se non la camicia che ho addosso!\n\nPerché mi guardi così...", nil, nil, 0x60f5ce71, 0xa9ff54a5, 0x25c4a902, nil, nil, "...mm" },
  [95483] = { "Thrall deve saperlo", "Porta a Thrall a Orgrimmar la notizia della sorte di Varian Wrynn.", "Thrall deve sapere cosa è successo qui. Mi incontrerò con Ulka e mi assicurerò che sia in grado di viaggiare prima di tornare a Orgrimmar, quindi confido che porterai queste informazioni al Capoguerra al posto mio.\n\nVai ora, soldato dell'⟦Horde=Orda⟧. Racconta al nostro Capoguerra quale destino è toccato a Varian Wrynn.", nil, nil, 0xc67a80c4, 0xb5f9470e, 0x25b24b0e, nil, nil, "...mm" },
  [95494] = { "Orgoglio ferito e pelli di leone", "Raccogli 6 Savannah Lion Hide dalle Savannah Matriarch e dai Savannah Patriarch nelle ⟦Barrens=Savane⟧.", "Mi serve qualcuno con un braccio forte per la spada e un po' di tempo libero, che mi aiuti a raccogliere delle pelli di leone. Mi brucia l'orgoglio chiedere un aiuto simile a un estraneo, ma di recente mi sono ferito a una gamba. Finché non guarisco non sono in condizione di andare a caccia, ma ho degli impegni da rispettare.\n\nDi solito i più grossi di questa zona hanno le pelli migliori, quindi comincia da quelli.", "Come va la caccia?", "Sì, questi andranno benissimo. Ho un accordo con un conciatore locale per consegnargli queste pelli grezze in cambio di vari articoli di pelle lavorata che uso come parte del mio mestiere.\n\nNon sono mai venuto meno alla mia parte dell'accordo, e nemmeno con il mio infortunio ho intenzione di iniziare ora.", 0x5b2ff02d, 0xce49bfcd, 0x5cce729a, 0xe02b27bb, 0x29852b6b, "....." },
  [95495] = { "Il conciatore eremita", "Porta il ⟦Bundle of Hides=Mucchio di Pelli⟧ all'eremita sulla cresta che domina i Colli Aridi, nelle ⟦Barrens=Savane⟧.", "Queste pelli sono destinate a un conciatore con cui commercio spesso. È una specie di eremita e vive da solo in cima alla cresta alle mie spalle. In questo momento non riesco ad arrampicarmi facilmente su un pendio così ripido, quindi ti sarei debitore se potessi fare tu la consegna.\n\nAh, a proposito dell'... aspetto di questo conciatore. Non c'è da allarmarsi. Nonostante l'apparenza, non è una minaccia. Te lo giuro.", "Salute, {class}. Cosa ti porta quassù, nella mia proprietà, oggi?", "Ti ha mandato Vrang, quindi? Molto bene. Ti ringrazio di avermi consegnato queste pelli. È un peccato che Vrang non abbia potuto fare il viaggio di persona. C'è una questione di cui desidero parlargli.", 0xc91f6041, 0x2e6fcebc, 0xf3a9275e, 0xbe27a510, 0xd3180b55, "....." },
  [95507] = { "La selvaggina di Vrang", "Raccogli 8 ⟦Trapped Game=Selvaggina Intrappolata⟧ dagli Sprung Trap nelle ⟦Barrens=Savane⟧.", "Già che sei là fuori, mi saresti di grande aiuto se dessi un'occhiata alle mie trappole. Le ho sparse per tutta la valle.\n\nRiportami la piccola selvaggina che ho catturato. Però tieni d'occhio gli altri animali. Questa zona può essere pericolosa, se non stai attent<o/a>.", "<Vrang ti grugnisce contro mentre ti avvicini.>", "Grazie per il tuo aiuto, {class}. Cominciavo a chiedermi se avrei dovuto andare a letto affamato stasera a causa di questa maledetta ferita alla gamba.", 0x56a6a9a8, 0xc7e5f7a1, 0xd203b57b, 0x8acd383f, 0xe4149abc, "....." },
  [95508] = { "Ospiti sgraditi", "Aiuta Walton a sopravvivere allo scontro con Terry Longdrink e i fanti di marina di Kul Tiras.", "Sì, un tempo ero nella marina di Kul Tiras. Dopo che il lord ammiraglio prese Theramore e cominciò la sua campagna in Durotar, avevo... delle \"obiezioni\" sui suoi metodi. Soprattutto su quelli che prevedevano di giustiziare i civili.\n\nLa storia è più lunga, ma... aspetta... cos'è quello?\n\nC'è un gruppo di uomini che sale lungo la cresta!", nil, "Be', a quanto pare siamo tutti vivi. Io... sapevo che un giorno questa storia mi avrebbe raggiunto. Ti sono debitore per l'aiuto di oggi.\n\nTi prego, prendi questo. Non è molto, ma è il minimo che possa fare.\n\nBuon viaggio, {class}.", 0xaedbb4a0, 0xfb874c5b, 0x5b6957f0, nil, 0xd4531345, "...m." },
  [95511] = { "Il tuo primo amico felino", "Ispeziona i felini da cavalcare per scegliere la tua prima cavalcatura.", "Salve, amico! Vedo che oggi è davvero un gran giorno: oggi ti legherai al tuo primo felino.\n\nCome saprai o forse no, questi felini sono ferocemente intelligenti ed estremamente leali al cavaliere a cui sono legati. Non troverai un compagno più nobile e saldo. Per questo hai davanti una scelta importante. Tu e il tuo felino viaggerete insieme per il mondo, quindi scegli con saggezza! Non temere, qualunque scelta farai sarà quella giusta.\n\nVai, esamina i felini e torna da me quando avrai deciso.", nil, nil, 0x67e095c9, 0x60d306c0, 0x76ee9d49, nil, nil, "...mm" },
  [95534] = { "Il mistero di Strahnbrad", "Risolvi il mistero di Strahnbrad e riferisci ciò che hai scoperto in paese, a ⟦Hillsbrad=Colletorto⟧.", "<Il biglietto è bruciacchiato in alcuni punti, ma ancora leggibile.>\n\nSi dice che quei vecchi mantici abbiano una volontà propria e prendano vita quando nessuno guarda. Non m'importa se è una storia di fantasmi: farai meglio a venirne a capo prima del mio ritorno.\n\nA Strahnbrad c'è un grande potere, lo so.\n\n< Il resto del biglietto è bruciato e strappato, come se fosse stato colpito da una magia del fuoco. >", nil, "Quindi c'era un elementale del fuoco che viveva nei vecchi mantici a Strahnbrad? Il vero mistero è come ci sia arrivato, suppongo. In ogni caso, ottimo lavoro. I tuoi sforzi saranno ricompensati.", 0x84d1d4cf, 0xe5975afe, 0x53e7de0b, nil, 0x9c3c9d9f, "...m." },
  [95555] = { "Natura corrotta", "Trova la fonte della corruzione del bastone a Feralas.", "<Dal bastone emana un'energia malsana che distorce del tutto il naturale fluire della magia intorno a te. Nonostante il disturbo, non riesci a posarlo. In lontananza avverti un'energia simile, altrettanto immonda, che risuona e ti attira a sé. Forse puoi trovare la fonte di questo oggetto maledetto.>", nil, nil, 0x4d49d908, 0x8fb1a9a1, 0xf124aede, nil, nil, "...mm" },
  [95561] = { "Mela dei miei occhi", "Raccogli $N1 Mela Fresca per Tessa Albachiara a Forte Farholde.", "<I forti strilli della piccola Albachiara echeggiano per Forte Farholde. Tessa ti guarda con un sorriso stanco.>\n\nOh, salve, <avventuriero/avventuriera>. Scusa il rumore. La piccola Emma oggi sembra piuttosto capricciosa, ma non so perché. Forse un po' di cibo aiuterà.\n\nPensi di potermi aiutare a trovare qualcosa da farle mangiare? Mio marito è uscito a prendere delle provviste e ho le mani un po' troppo occupate per andarci io. Se riuscissi a trovare qualche mela da queste parti potrei farle un bel purè.", "Non ti dicono mai quanto fare il genitore sia improvvisare man mano. Tutti lo fanno sembrare così facile.", "Grazie mille, {name}. Hanno un aspetto davvero delizioso. Di' grazie, Emma. Ringrazia <il/la> {class} gentile.\n\n<La bambina rifiuta il cibo e continua a piangere.>\n\nMm. Forse no.", 0xae845ae0, 0x4c19a9ea, 0xdecef8a0, 0x0cd097c9, 0xf8ee4815, "....." },
  [95562] = { "Tagliare le teste", "Uccidi Chogg'Zac nelle grotte sotto Radura Solare e recupera le loro teste per l'apprendista Claire.", "Ho una confessione da fare. Dama Salambra mi ha davvero mandato a raccogliere quei campioni, ma in verità mi sono offerto io. La Radura Solare era la mia casa prima che la guerra me la portasse via e non potevo riposare sapendo che dei mostri la contaminano ancora. Che siano un'orda o il Crepuscolo.\n\nNon c'è vittoria nell'imparare da loro. Non c'è niente da imparare. Sono bestie, semplici e pure, e vanno abbattute come bestie.\n\nDobbiamo uccidere il loro padrone in fondo a questa caverna e porre fine a tutto questo. Sono certo che la mia signora capirà.", nil, nil, 0xd07b970e, 0x6a3352c2, 0xdd4da7e5, nil, nil, "...mm" },
  [95568] = { "Semi per una nuova stagione", "Raccogli $N1 Seme Incontaminato per Ketharas.", "Sei <giunto/giunta> sul ⟦Mount Hyjal=Monte Hyjal⟧ in un periodo di cambiamenti, straniero.\n\nForse hai visto che il paesaggio è segnato dalla vecchia guerra e contaminato dalle energie vili. Perché Hyjal sopravviva, la natura deve fiorire di nuovo.\n\nSe sei disposto ad aiutarmi a raccogliere semi da alcune delle piante incontaminate, te ne sarei grato. Molti fiori crescono nelle terre selvagge a est di qui. Cerca piccoli fiori rossi o gialli.", nil, nil, 0x8ac09cb7, 0x75bbc9d2, 0x56f880ac, nil, nil, "...mm" },
  [95569] = { "Speranza per i piccoli", "Salva $N1 Uovo di Gufo di Hyjal e portali a Ketharas.", "I gufi sono minacciati dalla corruzione vile che affligge il fianco della montagna e dalle creature avvelenate e rese furiose da quelle energie. Molti gufi hanno abbandonato i loro nidi per luoghi più sicuri più in alto sulla montagna. Altri sono caduti a difesa dei loro piccoli.\n\nPerché i gufi abbiano un futuro, le loro uova vanno protette e i loro pulcini accuditi. Portami le uova abbandonate. Puoi trovare uova nei nidi abbandonati alla base degli alberi a nord e a est di qui.", nil, nil, 0xff967fe8, 0x1162ae92, 0x89270048, nil, nil, "...mm" },
  [95599] = { "La Vecchia Chiave", "Trova nelle vicinanze, a Feralas, il vecchio forziere a cui appartiene la chiave.", "<La chiave è ricoperta da un grosso strato di ruggine, il che suggerisce che sia rimasta sott'acqua per parecchio tempo.\n\nDeve esserci una serratura corrispondente nelle vicinanze su cui usarla, ma dovrai cercarla. Forse la pozza d'acqua a sud-ovest di questo accampamento potrebbe essere un buon punto di partenza?>", nil, nil, 0xc018f447, 0x1448bfc2, 0xf788a694, nil, nil, "...mm" },
  [95601] = { "Quelli viola", "Uccidi $N1 Bruto Potenziato e $N2 Ritualista del Crepuscolo, poi torna da Ditomazza a Radura Solare.", "<Questo ogre morto deve essere uno degli amici che Ditomazza cercava. Il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ sembra condurre rituali sui propri membri, potenziandone alcuni e uccidendone molti altri.\n\nQuesti ritualisti e le loro mostruosità vanno fermati prima che si diffondano.>", nil, nil, 0x494d5db5, 0x0bfcb3ae, 0xda294067, nil, nil, "...mm" },
  [95602] = { "Luci malsane", "Distruggi $N1 Circolo del Rituale del Crepuscolo nelle grotte sotto Radura Solare.", "Io odio rompere sassi. Tutto giorno io rompo. Chogg'Zac dice così. Lui grande capo. Dice noi rompiamo piccoli, ma ora lavoriamo per piccoli. Quello stupido.\n\nPerché rompere sassi? Io non so. Troviamo luce lucente nei sassi. Chogg'Zac piace lucente, io penso. Anche tu qui per luce lucente? Agli altri non piacerà. Loro piace molto luce. Disegnano immagini con luce.\n\nDitomazza non capisce. Luce fa sentire Ditomazza male. Io odio luce. Io voglio ROMPERE immagini lucenti! Ma Chogg'Zac sarà arrabbiato. Schiaccia Ditomazza. Brutto. Ma qualcuno dovrebbe.", nil, nil, 0xaf1ab0d2, 0xe30ca35a, 0xb631f163, nil, nil, "...mm" },
  [95603] = { "Pipistrelli nel campanile", "Uccidi 5 Pipistrello del Vespro Appollaiato nella Cattedrale di Farholde per sorella Rowland.", "Da quando fratello Lowley e io abbiamo iniziato a servire Farholde in veste più secolare, la chiesa qui è caduta in disuso. Mi piace pensare che, una volta finita la lotta, potremo riportare la Luce in questo luogo. Anche se temo che non accadrà per molto tempo...\n\nCi serve comunque tenere la chiesa in ordine, nella speranza che quel giorno arrivi.\n\nA tal fine, una colonia di pipistrelli ha iniziato a nidificare ai piani superiori della chiesa. Sarebbe di grande aiuto se potessi rimuoverli.", nil, "Hai un animo buono, {class}. Grazie.", 0xac70e617, 0xc749222c, 0x43852880, nil, 0x0596a430, "...m." },
  [95611] = { "Riti di rispetto", "Seppellisci i resti al santuario di Ketharas.", "Non si può prendere senza dare in cambio. Questo è il ciclo della vita.\n\nHai fatto bene, {name}. Grazie ai tuoi sforzi, la fauna sulla montagna continuerà a prosperare.\n\nOra è il momento di mostrare il nostro rispetto per queste terre restituendo alla terra i resti non utilizzati.\n\nPrendi questo fagotto e visita il santuario a ovest. Lo riconoscerai: è una semplice coppia di pietre erette. Torna da me quando il rituale sarà completo.", nil, nil, 0x8ad3bcf7, 0x96007aba, 0x33bf85b5, nil, nil, "...mm" },
  [95613] = { "Tenere accesa la luce", "Porta $N1 Candela Sacra a sorella Rowland a Forte Farholde.", "Anche se non teniamo più funzioni in chiesa, ritengo importante tenere accese le candele sulle tombe dei nostri caduti nella cripta della chiesa. Per me, mantenere viva la fiamma della candela è un simbolo che non sono dimenticati e che i loro sacrifici non sono stati vani.\n\nSe non ti dispiace, portami delle candele così che io possa continuare questo rituale. Significherebbe molto per me.\n\nSe non sai dove trovarle, parla con Marla nella casa appena fuori dalla chiesa. È un'amica e potrebbe averne da darti.", "So che qualche candela è un gesto piccolo nel grande schema di ciò che facciamo qui, ma come mi prendo cura dei vivi, così devo prendermi cura dei morti.", "Andranno meravigliosamente. Ti ringrazio ancora per l'aiuto, {name}.", 0x53bbf370, 0x9a606ab7, 0xea1081ff, 0x7bab6bb6, 0xb0ae9508, "....." },
  [95615] = { "In memoriam", "Posa $N1 Candela Commemorativa sulle tombe nel cimitero della cappella per sorella Rowland a Forte Farholde.", "Se non ti dispiace, vorrei che tu avessi l'onore di accendere queste candele commemorative. Vai al cimitero qui fuori e metti una candela nuova ovunque ne vedi una spenta.\n\nUn compito del genere è ben lontano dall'emozione delle tue altre avventure, ne sono certo. Consideralo un'opportunità di servizio e riflessione: un momento di quiete per riconoscere chi ha lasciato questo mondo prima di noi, affinché noi possiamo andare avanti e renderlo un posto migliore.", "Hai finito le candele, {name}?", "Le anime dei nostri caduti ti guardano con calore e gratitudine, come faccio io.\n\nGrazie per aver aiutato a mantenere viva la chiesa, {name}. Che la Luce ti guidi e ti protegga nel tuo viaggio.", 0x055586d2, 0xaef8d28f, 0x0cd602b9, 0x6d631b46, 0xb5e5e256, "....." },
  [95621] = { "Guai nella valle", "Raggiungi la carovana distrutta e scopri di più sul perché i Kul Tirani sono qui.", "Stamattina ho visto un gruppo di umani che cercava qualcosa nella valle qui sotto. Sono riuscito a guardarli meglio con il mirino del fucile, ed era chiaro che erano soldati con le insegne di Kul Tiras.\n\nSe sei dispost<o/a> a lavorare per me, raggiungi il punto in cui questi soldati si sono accampati, vicino alla carovana distrutta a sud. Uccidi tutti quelli che trovi e cerca di scoprire perché sono qui.", "Ciò che resta della flotta di Daelin Proudmoore, che ancora ne innalza lo stendardo, è marcio e barbaro quanto lo era l'ammiraglio prima di morire.\n\nNon so perché siano così lontani da Tiragarde, ma non può essere niente di buono.", "Quindi cercano un disertore... Be', sembra che il passato mi abbia finalmente raggiunto.", 0x389c29a3, 0xef54682f, 0xcaabc078, 0xdcde325c, 0x518baf21, "....." },
  [95642] = { "Magie abominevoli", "Assorbi $N1 campioni nel Catalizzatore di Cristallo dai cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ e dai Circoli del Rituale del Crepuscolo nella grotta sotto Radura Solare per l'apprendista Claire.", "Ehi, tu! Per fortuna sei arrivato. Ti ha mandato Salambra a cercarmi?\n\nNo? Immaginavo. Ashe Salambra mi ha mandato quaggiù a indagare sul ⟦Twilight's Hammer=Martello del Crepuscolo⟧. Come vedi, stanno scavando per qualcosa nelle Radure del Fiume, ma mi serve un campione della loro stregoneria per capire cosa.\n\nÈ fondamentale che Farholde ottenga quei campioni. Ti prego, {class}. Prendi questo catalizzatore. È incantato per assorbire i poteri del culto. Rune, cultisti, non importa. Tienilo alto e farà il resto.", nil, nil, 0xda2c4edb, 0xa3c91c9c, 0x35d2d396, nil, nil, "...mm" },
  [95643] = { "Epurazione indiscriminata", "Uccidi $N1 Ritualista del Crepuscolo e $N2 Bruto Potenziato nelle grotte sotto Radura Solare.", "Come apprendista di dama Salambra nelle arti oscure, forse non sembra, ma di solito sono perfettamente in grado di cavarmela in autonomia. Non avevo però previsto un'intera caverna di ogre intrisi di Vuoto.\n\nSe ce l'hai fatta ad arrivare fin quaggiù senza farti catturare, devi essere potente anche tu. Io non ho avuto la stessa fortuna con quegli ogre e i loro padroni che si aggirano da queste parti. Fai un favore al mondo e uccidi quelle bestie orribili. Niente di buono viene da un fanatico con uno scopo, potenziato o meno.", nil, nil, 0x274a4d72, 0x9d6406b2, 0xfbebad5b, nil, nil, "...mm" },
  [95646] = { "Orrori sull'altopiano", "Uccidi un Highland Horror negli Excavation Sites e porta il suo nucleo radicale a ⟦Rethiel the Greenwarden=Rethiel il Guardiaverde⟧, nelle ⟦Wetlands=Paludi Grigie⟧.", "Queste paludi salmastre custodiscono una riserva più grande delle acque dolci del sud. Mi addolora, eppure nelle mie radici sento una corruzione che filtra da quella gola di montagna.\n\nLe creature, come quelle delle nostre terre basse, reagiscono con più asprezza alla contaminazione. Prive fin dall'alba della vita del sale che tempra il mare, hanno poca forza contro un simile male.\n\nVa' su quegli altopiani e portami il nucleo radicale dell'Highland Horror.", "Queste acque ospitano una vita unica in una salamoia che dà e toglie in egual misura.", "È peggio di quanto temessi. Un'energia antica si agita. Sarebbe molto saggio da parte tua riferire ai tuoi entusiasti scavatori di smettere di scavare, per la loro stessa sicurezza.", 0x79650957, 0x81ee8465, 0xbce12a7e, 0xe589bde8, 0xafb47264, "....." },
  [95647] = { "Perso nella boscaglia", "Trova Ardin Grassman negli Excavation Sites.", "Mio marito, Ardin, ha un raro dono per percepire la natura. Si arrampica su qualsiasi vetta per raccogliere le erbe e i fiori che mi servono per l'alchimia, e così i nostri scaffali e la dispensa restano sempre pieni.\n\nMa temo che si sia cacciato nei guai. È passata di qui una squadra di scavo in cerca di provviste. Tra le altre cose, parlavano di erbe altissime, diverse da qualsiasi cosa avessero mai visto. Mi ha detto che doveva andare a vederle con i suoi occhi. È via da troppo tempo!\n\nSe scopri qualcosa su di lui, te ne sarò grata.", nil, "Pensavo fossimo spacciati! Qualcosa ha agitato la fauna da queste parti e la nostra squadra di scavo è stata sopraffatta. Grazie per averci aiutato con quei ragni.", 0xc3371e69, 0x4d0fc432, 0x6d7c1497, nil, 0x80efe02a, "...m." },
  [95663] = { "Voci sulle Fauci di Drago", "Raggiungi le ⟦Wetlands=Paludi Grigie⟧ e incontra l'⟦Deathstalker Agent=Agente Inseguitore della Morte⟧ sulle colline sopra l'accampamento delle Fauci di Drago.", "Le Fauci di Drago sono un clan temibile.\n\nSono noti per una magia vincolante abbastanza forte da piegare i draghi al loro servizio, e si dice che stiano preparando una dimostrazione di questo potere nelle ⟦Wetlands=Paludi Grigie⟧. Che sia verità o millanteria, gli ⟦Deathstalkers=Inseguitori della Morte⟧ non possono agire su sussurri appena abbozzati. Dei simboli corrotti non mi hanno detto altro.\n\nUn'agente degli ⟦Deathstalkers=Inseguitori della Morte⟧ ha bisogno di una mano sulle colline sopra l'accampamento delle Fauci di Drago. Raggiungila lì. Ti rivelerà i prossimi passi.", nil, "L'arrivo dei pochi coraggiosi? Abbassa la voce.", 0xecfb9de3, 0x607aac05, 0x19f544b5, nil, 0xb788f065, "...m." },
  [95664] = { "Il sapere degli antichi", "Porta la ⟦Titan Relic=Reliquia dei Titani⟧ all'⟦Elder Rise=Altura degli Anziani⟧, a ⟦Thunder Bluff=Picco del Tuono⟧, e cerca qualcuno che possa dirti di più al riguardo.", "Questo insolito frammento composito diffonde la luce come un prisma vivente. La sua natura è incerta, ma il suo potere sembra antico. Le menti più esperte di manufatti di quell'epoca remota devono trovarsi sull'Altura degli Anziani, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Gli spiriti ti onorano. Sei venut<o/a> a condividere qualcosa con noi?", "È un segno favorevole che uno straniero si avvicini in questo modo. Sento un potere attorno a te... cos'è che hai portato?", 0x1d764e46, 0x4a860375, 0xd36a8f92, 0x849d94ef, 0xf0e44ff1, "....." },
  [95682] = { "Aprire le fauci", "Uccidi le forze delle Fauci di Drago negli Excavation Sites e torna dall'⟦Deathstalker Agent=Agente Inseguitore della Morte⟧, all'esterno, con tutto ciò che recuperi.", "Fauci di Drago. <Si lascia sfuggire uno sbuffo secco e divertito.>\n\nQuel che resta del clan dei domatori di draghi crede di aver trovato qualcosa che potrebbe riportarlo al potere di un tempo. Agli occhi di chi... del loro falso Capoguerra?\n\nSpazza via quel clan raffazzonato dagli Excavation Sites, così che i nostri ⟦Deathstalkers=Inseguitori della Morte⟧ possano entrare senza essere scoperti.\n\nSe le Fauci di Drago hanno addosso qualcosa di interessante, portalo a me: queste informazioni devono restare tra noi e il nostro comando reale.", "Siamo qui per portare a termine un lavoro importante. Se puoi aiutarci, dimostralo.", "Non badare se te lo strappo di mano.\n\nHo riconosciuto quegli scarabocchi orcheschi. Quindi sperano di ingraziarsi Rend? Uno sforzo inutile e sprecato.\n\nPoco importa: per la Dama Oscura è un'informazione preziosissima.\n\nTieni, non porterò via niente di tutto questo... e non parlare della missione, soldato.", 0x01716485, 0x9fb46d83, 0x5cd87c72, 0xe5a6f90f, 0xd5c4e240, "....." },
  [95697] = { "Gusti che cambiano", "Entra negli Excavation Sites, nelle ⟦Wetlands=Paludi Grigie⟧, e riporta della ⟦Thicket Raptor Meat=Carne di Raptor del Boschetto⟧.", "Zamja dice che ci serve più cucina casereccia.\nSe cominciamo a vendere carne di raptor, secondo lei attirerà clienti che di solito non passano dal Borstan's Firepit.\n\nNon è una cattiva idea. Ma io voglio qualcosa che vada oltre i sapori dei nostri villaggi natii. Siamo a Orgrimmar! Borstan dovrebbe servire una versione grandiosa dei loro piatti preferiti di sempre.\n\nUn cacciatore è appena tornato dalle ⟦Wetlands=Paludi Grigie⟧ con un artiglio gigante dei raptor della boscaglia degli Excavation Sites.\n\nTi va un lavoretto?", "Cinghiale d'allevamento, crawler d'allevamento... e poi? Raptor d'allevamento?", "Guarda che marezzatura! Cosa mangiano lassù? Grazie per aver fatto tutta quella strada per noi, andata e ritorno. Se non ti dispiace aspettare, te ne cuciniamo un po' adesso, offre la casa, naturalmente!", 0xefd7f8a7, 0x406ca9c2, 0xc77dbee9, 0xaf7bf20a, 0x96c0ebac, "....." },
  [95737] = { "In cerca di Caitlin", "Parla con ⟦Caitlin Grassman=Caitlin Seccafieno⟧ al ⟦Menethil Harbor=Porto di Menethil⟧.", "Ogni tanto scrivo ad altri del mio mestiere: erboristi o eccentrici che studiano piante rare e curiosità locali. Ci scambiamo scoperte, e a volte avvertimenti su ciò che ci aspetta.\n\nUn'alchimista delle ⟦Wetlands=Paludi Grigie⟧ mi ha scritto di una squadra di scavo di cui faceva parte suo marito, che aveva trovato tracce di un'erba primordiale perduta da tempo... ma non mi ha mai fatto sapere se fosse abbondante o facile da raggiungere.\n\nSe puoi, va' a vedere come sta ⟦Caitlin Grassman=Caitlin Seccafieno⟧ al ⟦Menethil Harbor=Porto di Menethil⟧.", nil, "Llana si starà chiedendo dove siano quei semi d'erba che avevo promesso avrei fatto portare da mio marito! Mi consola sapere che è preoccupata quanto me. Dev'essere qualcosa del sito di scavo stesso che entrambe percepiamo.", 0xf6e09b80, 0x29283070, 0xb0744041, nil, 0xe950e46a, "...m." },
  [95748] = { "Le antiche leggende dei Gurubashi", "Usa la pelle e il carboncino per ricavare un calco della tavoletta della terza leggenda troll.", "Strano. Questo pezzo di tavoletta che mi hai portato parla della città perduta di I'lalai come di una civiltà vasta e sterminata. Ma le rovine al largo della scogliera non sono abbastanza grandi per qualcosa di quelle dimensioni.\n\n{name}, a nord della Scogliera Infame, sulle colline lungo la costa, c'è un'antica rovina troll. Al suo interno c'è una tavoletta che contiene le leggende della città troll perduta. Desidero studiare meglio questa leggenda.\n\nPrendi questa pelle e questo carboncino e ricava un calco della tavoletta, poi torna da me.", nil, nil, 0x1163f14b, 0x8eb3fa59, 0x85f90475, nil, nil, "...mm" },
  [95751] = { "Strani totem", "Esamina gli strani totem a Tanaris.", "Gli spiriti mi hanno mostrato una visione di calore, sole e infinite dune ondulate. Una coppia di totem scolpiti e solitari, che sovrastano le ossa di una possente bestia semisepolta dalle sabbie del tempo. Mi sono state mostrate le colline desertiche di Tanaris, ne sono quasi certo.\n\nLo scopo dei totem non mi è noto, ma di certo c'è uno scopo per la loro solitaria veglia. Desidero che tu cerchi questo luogo e veda se riesci a risolvere il mistero.", nil, nil, 0x3f7693ec, 0xd7cd93ec, 0x48939bee, nil, nil, "...mm" },
  [95753] = { "La sfida del lupo del deserto", "Raggiungi l'altro strano totem alla fine dell'enorme scheletro prima che scada il tempo.", "<Il totem pulsa di magia selvaggia. Nella tua mente appare l'immagine di un lupo spettrale che ti fa cenno di avvicinarti.\n\nSembra che ti stia offrendo una sfida.\n\nUn altro totem, gemello di quello su cui ora posi la mano, appare in lontananza, appena oltre il grande scheletro sbiancato dal sole lì vicino.>", nil, nil, 0x7077552d, 0xfe6a9947, 0xc92e5370, nil, nil, "...mm" },
  [95766] = { "Un amico piumato", "Trova lo strano uccello nelle terre corrotte sul versante sudoccidentale.", "Il ciclo del rinnovamento è finalmente iniziato. Gli antichi... sorgeranno di nuovo, e il potere del mondo naturale seguirà il suo corso... per sbocciare.\n\nTu... ci hai aiutato a far pendere la bilancia a favore della natura. Forse... possiamo ancora avere un impatto maggiore... su una situazione più grave.\n\nDirigiti a ovest... dove la terra stessa è color cenere... e potresti trovare un'entità che può aiutare. Può sembrare solo un piccolo uccello... ma il suo potere è grande.", nil, nil, 0xa3a492c4, 0xe6acf687, 0x9b0b8249, nil, nil, "...mm" },
  [95769] = { "Tessere una soluzione", "Porta $N1 Rotolo di Telarunica a Mez'dan nella Selva Antica, sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Ogni giorno è una sfida quando si vive all'addiaccio come facciamo noi! Mette a dura prova attrezzi, vestiti, la vita intera. Per fortuna non può toccare il nostro spirito!\n\nStiamo soffrendo parecchio per i vestiti e le coperte che si consumano. Tu fai un po' di sartoria, vero? Allora forse puoi portarmi dei Rotoli di Telarunica e io posso rimediare qualche buco?", nil, nil, 0x81f5dfe5, 0x44f58216, 0x165d7577, nil, nil, "...mm" },
  [95770] = { "Sulle tracce della città perduta", "Esplora la Scogliera Infame e trova l'ingresso della caverna.", "Dopo aver riletto la leggenda, non sembra che stiamo cercando la città perduta nel posto sbagliato, ma forse c'è ancora qualche dettaglio che ci è sfuggito.\n\nDa giovane mi immergevo tra le rovine della Scogliera Infame, ma era prima che vi si stabilissero i murloc. Se la memoria non m'inganna, laggiù c'era una caverna.\n\nHo sentito che ora in quella zona si stanno radunando dei naga, cosa insolita. Voglio sapere che cosa li ha attirati lì.\n\nVa' a esplorare appena a ovest della Scogliera Infame e torna da me con qualunque notizia.", nil, nil, 0xbfc53c6c, 0x5befc8cb, 0xba46d29c, nil, nil, "...mm" },
  [95771] = { "Un assaggio di oscurità", nil, nil, nil, nil, 0x8583a882, nil, nil, nil, nil, ".mmmm" },
  [95772] = { "Alla ricerca di Songblade", "Cerca Daewyn, il fratello di Dorin Songblade, agli ⟦Whelgar's Excavation Site=Scavi di Whelgar⟧.", "Mio fratello ha provato a trascinarmi nelle ⟦Wetlands=Paludi Grigie⟧ con una squadra di scavo partita da Loch Modan. Diceva che andavano su colline dove nessun nano ha mai messo piede, per non so che scavi.\n\nEh, ci sarei pure andato, se non fossi già in ritardo con 'sta pila di cinture da sistemare.\n\nDi solito, però, Daewyn scrive quando parte. Non ho saputo niente, e stavolta ho una brutta sensazione.\n\nSe vai da quelle parti, ti spiace dare un'occhiata a mio fratello?", nil, "Questo nano ha una forte somiglianza con ⟦Dorin Songblade=Dorin Sibilama⟧. Il fucile nelle sue mani ha le lettere «DLS» incise sul calcio.", 0x4225ee40, 0x72145fde, 0x91fbce45, nil, 0x6d007b3d, "...m." },
  [95773] = { "Nemici nell'acqua", "Raccogli $N1 Brinescale Trident dai Brinescale Skirmisher.", "{class}, arrivi al momento giusto. Ho appena ricevuto nuovi rapporti su un'attività dei naga proprio al largo della nostra costa. Sembra che sciamino attorno ad alcune vecchie rovine troll vicino al fondale.\n\nSiamo già allo stremo per difenderci dagli Scalporosso della zona e dagli ogre che saccheggiano le nostre carovane. Non possiamo permetterci un attacco a sorpresa dal mare.\n\nVa' e uccidine quanti più puoi, e portami i loro tridenti come prova del tuo successo.", nil, nil, 0xf6a51353, 0x23c1e22b, 0xbd430784, nil, nil, "...mm" },
  [95774] = { "Il suo nome è Olgra", "Uccidi i verrospini e raccogli $N1 ⟦Olgra's Adornments=Ornamenti di Olgra⟧ per il memoriale di Mankrik.", "Chi mi ha guarito non è riuscito a salvare lei, ed è morta in battaglia. Il suo nome è Olgra, e non la dimenticherò mai.\n\nNon hai trovato i suoi ornamenti sul corpo? Portava molti gioielli d'osso levigato.\n\nUccidi i Razormane Raider vicino al punto in cui è caduta e trova le sue preziose opere d'arte!\n\nLi metterò accanto al memoriale che sto costruendo in sua memoria.", "Ora mi restano solo i ricordi, ma costruirò un tributo a Olgra perché non svaniscano mai.", "Metterò questi ornamenti accanto al memoriale di mia moglie, così da non dimenticarla mai. Il mio sangue ribollirà sempre di vendetta!\n\nHai fatto a me... a noi... un grande favore, {name}.", 0xe0733c23, 0x64b2ed87, 0x1085cf6b, 0xcb32b1fe, 0x22fd675b, "....." },
  [95775] = { "La Drowned City", "Usa la pelle e il carboncino per ricavare i calchi delle tavolette che trovi nella Drowned City.", "Ciò che sto per chiederti non è un'impresa da poco, {class}, e probabilmente ti serviranno alleati forti per riuscirci.\n\nVoglio saperne di più sulle rovine dall'altra parte della caverna sorvegliata dai naga. Se i miei sospetti si rivelano fondati, potrebbe davvero trattarsi della città perduta di I'lalai. La quantità di sapere storico perduto a portata di mano potrebbe essere senza pari, ma sono troppo vecchio per avventurarmi di persona.\n\nEntra nelle rovine e ricava i calchi delle tavolette che trovi, poi torna da me.", nil, nil, 0x7b66254a, 0xda9d19e9, 0xf184a1b6, nil, nil, "...mm" },
  [95776] = { "L'unico Brinescale buono...", "Uccidi Var'Taka nella Drowned City.", "Hai fatto bene a uccidere i naga al largo della nostra costa, ma il fatto che siano nelle nostre acque in così gran numero significa che c'è una minaccia ancora più grande.\n\nHo parlato con Kin'weelay, e lui pensa che questi naga Brinescale si stiano infiltrando nelle rovine della Drowned City. Se i naga sono lì, non tramano niente di buono e probabilmente stanno cercando qualcosa.\n\nNon possiamo permettere che mettano le mani su qualcosa che potrebbe comprometterci qui, ed è ora di porre fine a tutto questo. Uccidi il loro capo e torna da me.", nil, nil, 0x6893b9a2, 0x0ab0d353, 0xee8da360, nil, nil, "...mm" },
  [95786] = { "Un conoscente a ⟦Southshore=Riva del Sud⟧", "Trova lo ⟦Loremaster Dibbs=Storico Dibbs⟧ a ⟦Southshore=Riva del Sud⟧ e portagli il Fascio di Rapporti della Costa Selvaggia.", "{name}, ho un amico nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧ che studia le leggende dei troll e la magia malvagia. Credo che possa avere un'intuizione su come questa magia immonda abbia catturato la mente del colonnello Kurzen.\n\nHo anche un rapporto di un esploratore secondo cui i troll locali sembrano agitati, e menzionano la parola... \"I'lalai\".\n\nDevo sapere se è collegato alla corruzione di Kurzen! Tieni, porta i feticci e le leggende insieme a questo rapporto di ricognizione allo ⟦Loremaster Dibbs=Storico Dibbs⟧. Con un po' di fortuna riuscirà a svelare alcuni dei loro segreti.", nil, "⟦Brother Nimetz=Fratello Nimetz⟧ ti ha mandato fin da Rovotorto? Hai fatto un bel viaggio, allora. Dev'essere una questione di una certa importanza.\n\nVieni, dimmi cosa ti ha portato fin qui, a ⟦Southshore=Riva del Sud⟧.", 0x519d5781, 0x96558c64, 0x8f76ce25, nil, 0xe419f0b9, "...m." },
  [95787] = { "Due dosi, con acqua", "Usa la pelle e il carboncino per ricavare i calchi delle tavolette che trovi nella Drowned City.", "<Le mani dello storico Dibbs tremano mentre legge il rapporto di ricognizione e le leggende troll.>\n\nPossibile? Da questo resoconto sembra che la città troll perduta di I'lalai sia riemersa proprio al largo della costa di Rovotorto! Dobbiamo indagare subito. Ebbene, se le mie ricerche sono corrette, questa potrebbe essere la scoperta archeologica del secolo!\n\nTi prego, so che il viaggio fino a Rovotorto è lungo, ma se ti trovi nella Drowned City, raccogli tutte le leggende che trovi e riportamele.", "Mi chiedo se i miei amici della Lega degli Esploratori abbiano avuto notizia di quest'isola emersa--\n\nOh! {name}, sei tornat<o/a>. Hai visitato le rovine dei troll? Hai trovato nuove leggende?", "Quattro nuove tavolette! Questa è davvero una notizia fantastica.\n\nIl mio zandali antico è un po' arrugginito, ma queste leggende sembrano riferirsi a una... entità chiamata il Loa di--\n\n<⟦Loremaster Dibbs=Storico Dibbs⟧ strizza gli occhi guardando la pergamena.>\n\nMaree? N-non riconosco questo titolo! Meraviglioso, {name}! Potremmo essere incappati in un nuovo loa!", 0x8a52ce4a, 0xda9d19e9, 0xfa014234, 0xaf08e8fb, 0xa83c89ac, "....." },
  [95788] = { "Le magie della Drowned City", "Raccogli $N1 I'lalai Fetish dai troll della Drowned City.", "I feticci dei Fendicranio che fratello Nimetz ti ha affidato sono davvero potenti, anche se non credo abbiano contribuito alle condizioni di Kurzen, o almeno non direttamente.\n\nTuttavia, se le voci sono vere e la città troll perduta di I'lalai è davvero risorta dalla sua tomba d'acqua, è possibile che le magie oscure usate per sollevare la città maledetta siano collegate.\n\nSe osi avventurarti nella Drowned City di I'lalai, raccogli tutti i feticci troll che trovi e portali qui da me perché possa studiarli.", "Hai viaggiato fino alla leggendaria Città Sommersa? Cos'hai trovato?\n\nVieni, voglio sentire tutto ciò che hai visto nei minimi dettagli, se hai tempo.", "Non sono un mago, ma persino io vedo quanto siano diversi dai feticci che ho esaminato prima. La loro costruzione è per certi versi più intricata, ma per altri più semplice. Sembrano anche raffigurare un grande serpente marino di qualche tipo.\n\nAffascinante.\n\nCon quello che mi hai detto su morti viventi vaganti, pirati invasori, rituali di sangue e forze naga che convergono tutti sulle rovine, sembra che I'lalai sia ora un focolaio di molti tipi di magia che si mescolano insieme.\n\nQuesto richiede certamente ulteriori studi.", 0xe9ed0635, 0xd05a8a60, 0xcb7fb810, 0x88c7e996, 0x04dd47c5, "....." },
  [95789] = { "Scrutasale loschi", "Raccogli $N1 Manufatto Infuso di Voodoo dai pirati Scrutasale nella Città Sommersa.", "Ehi amico, hai l'aria di uno che sa cavarsela in un combattimento.\n\nIl ⟦Baron Revilgaz=Barone Granbottino⟧ mi fa tenere l'orecchio a terra per gli oggetti magici. Si dice in giro che una rovina troll sommersa sia misteriosamente, ehm, riemersa, il che significa che ci sono molte merci non reclamate, se capisci cosa intendo.\n\nIl problema è che ha attirato anche l'attenzione dei pirati! E non pirati qualsiasi, gli Scrutasale raccolgono specificamente manufatti magici. Ho bisogno che tu vada nella Città Sommersa, li elimini e prenda i loro manufatti rubati.", "Ehi! Hai già avuto modo di sistemare quei maledetti pirati? Ho una ciurma pronta a partire per saccheggiare... ehm, esplorare le rovine dei troll.", "Eccellente! Informerò subito il Barone.\n\nCome promesso, ecco la tua parte della ricompensa.", 0xddbc09c1, 0xf479884c, 0x3fab9ac8, 0xe2783504, 0x795bba69, "....." },
  [95790] = { "Ricerca digeribile", "Raccogli $N1 Pagina di Diario Parzialmente Digerita dalla Terrazza del Plasmatore.", "<Questo diario sembra essere stato fatto a brandelli. Da quel poco che riesci a decifrare, pare il diario di campo di uno degli sfortunati avventurieri della ⟦Explorers' League=Lega degli Esploratori⟧.\n\nI segni di masticazione all'esterno del diario suggeriscono che siano stati con ogni probabilità dei raptor.\n\nForse le sue pagine possono essere trovate e ricomposte.>", nil, nil, 0x836fcb41, 0xd7e9c098, 0x0d015ad8, nil, nil, "...mm" },
  [95791] = { "Il capitano degli Scrutasale", "Uccidi 3 Medico Legale Scrutasale e il Capitano Sorgiterrore nella Città Sommersa.", "I pirati Scrutasale sono stati una spina nel fianco di recente e sapere che sono nella Città Sommersa peggiora le cose! Cioè, sono sempre una brutta notizia, ma c'è un capitano in particolare che voglio fuori dai piedi. Quel maledetto capitano Sorgiterrore!\n\nLui e la sua ciurma sono molto abili a raccogliere tutti i manufatti magici che sto cercando, e sono stanco della concorrenza.\n\nVoglio che tu tolga di mezzo il capitano Sorgiterrore e i suoi Medici Legali Scrutasale. Per sempre.", nil, "Non so come ringraziarti! Dormirò meglio sapendo che ci sono meno Scrutasale in giro.\n\nSo che anche il Barone apprezza il tuo servizio. Ecco la tua taglia.", 0xe6ca7f0e, 0x94a2411c, 0x1f831f71, nil, 0x0e9f7c2c, "...m." },
  [95792] = { "Ripulirli", "Uccidi $N1 Cucciolo Scagliacenere e $N2 Guerriero Scagliacenere per Gelinda Lucerame.", "Se vuoi fare un colpo grosso, devi andare dove gli altri non oserebbero! Questa caverna dietro di me è ricca di giacimenti minerari inutilizzati. Parlo di un SACCO di soldi se riusciamo a mandarci dentro una squadra.\n\nC'è solo questo... piccolissimo... problema di draghi. Non è niente, davvero.\n\nSe te la senti di entrare e risparmiarmi la fatica di sgombrare i draghi, c'è una bella ricompensa per te. Per non parlare del fatto che ti ingrazierai un futuro magnate dell'estrazione!", nil, "Ottimo lavoro, {class}. Quando la mia piccola impresa mineraria comincerà a dare profitti, ti prometto che ti farò entrare nell'affare!", 0x12e349a6, 0xcb97e782, 0x58264e6b, nil, 0xdc7be001, "...m." },
  [95793] = { "Arginare la marea demoniaca", "Uccidi $N1 Sentinella Vilguardia a Dae'gun.", "Ah, un {class}. Vedo in te grande forza e determinazione: qualità necessarie per liberare queste terre dal male.\n\nI demoni che percorrevano queste terre durante la grande battaglia furono sconfitti, ma alcuni rimangono ancora. È importante impedire loro di fuggire.\n\nLe rovine a est sono pericolose. Porta la tua forza nella loro tana. Distruggi gli indesiderati prima che le nostre terre periscano.", nil, nil, 0x0ab6e3d6, 0x4cc3c1f7, 0x08d863a8, nil, nil, "...mm" },
  [95795] = { "Caduto nella palude", "Torna da ⟦Dorin Songblade=Dorin Sibilama⟧.", "<Copri il corpo del nano con il suo mantello.>\n\nVa' a ⟦Lakeshire=Borgolago⟧ e informa di persona ⟦Dorin Songblade=Dorin Sibilama⟧ di ciò che è accaduto a suo fratello negli Excavation Sites.", nil, "Ah no...\n\n<Seppellisce la testa tra le mani e singhiozza.>\n\nAvrei dovuto andare con loro.\n\nGran parte di ciò che stavo forgiando era per lui, stavo preparando una sorpresa ma non era pronta quando è passato a prendere le cose per il suo viaggio.\n\nOra che sono finite, non ho il cuore di rifondere o vendere nulla.\n\nPuoi prenderlo tu. È il minimo che io possa fare per te, che mi porti questo giorno funesto.", 0xbfc85885, 0x2739cdb1, 0x9e5ae38b, nil, 0x42ec67db, "...m." },
  [95798] = { "La trama della magia", "Porta il Feticcio di I'lalai ad Abra Cadabra a Dalaran.", "{name}, voglio che tu porti questo Feticcio di I'lalai alla mia amica Abra a Dalaran. Mi piacerebbe che lo esaminasse, se ne ha il tempo.\n\nÈ anche particolarmente interessata alle pratiche e alla magia dei troll, quindi credo che questa scoperta sarà entusiasmante da decifrare per lei.\n\nFai attenzione, però. Il Kirin Tor può essere un po' schizzinoso su chi lascia entrare nella sua grande città. Se non sei già un visitatore degno di nota, potresti dover trovare un modo per ingraziarti la sua benevolenza.", nil, "Per tutti i cieli! La quantità di magie diverse e contrastanti che tirano questo feticcio è notevole. È certamente un bene che tu me l'abbia portato.\n\nIn mani sbagliate potrebbe essere molto pericoloso se non maneggiato con estrema cautela.\n\nGrazie per averlo portato fin qui, {class}. Invierò subito i miei risultati allo ⟦Loremaster Dibbs=Storico Dibbs⟧.", 0x71ee526c, 0xc2dcabde, 0x4e9e940b, nil, 0x1e544c8b, "...m." },
  [95799] = { "Scoperte per la Lega degli Esploratori", "Porta le Traduzioni di I'lalai dello ⟦Loremaster Dibbs=Storico Dibbs⟧ a ⟦Historian Karnik=Karnik lo Storico⟧ a ⟦Ironforge=Forgiardente⟧.", "Devo scrivere subito al mio collega a ⟦Ironforge=Forgiardente⟧, alla Lega degli Esploratori. È una scoperta di proporzioni storiche.\n\nTi dispiacerebbe consegnare la lettera a ⟦Ironforge=Forgiardente⟧ per me? Ti scriverò una copia delle mie traduzioni delle tavolette.", nil, "Ah, lo ⟦Loremaster Dibbs=Storico Dibbs⟧ non manca mai di portarmi cose di grande interesse. Anche se il mio campo di studi non si concentra sui troll, posso certamente apprezzare la sua passione.\n\nÈ un'ottima notizia. Metterò insieme una squadra per partire subito alla volta di questa città perduta di I'lalai!", 0x1711b4d8, 0x6a18ec59, 0x10b2059b, nil, 0x08d0aa03, "...m." },
  [95803] = { "Un pegno di buona fede", "Porta la testa di Rudolph Gelhardt a Sylvanas Windrunner, a ⟦Undercity=Sepulcra⟧.", "Ora che abbiamo preso la testa del comandante caduto in disgrazia, devi consegnarla a ⟦Undercity=Sepulcra⟧. Sylvanas Windrunner diffida molto di noi, e ci disprezza quasi apertamente.\n\nConsegna la testa di Rudolph Gelhardt alla Dama Oscura. Dimostrale che sappiamo mettere ordine in casa nostra e che siamo devoti alla prosperità dei Reietti.", "Perché ti rivolgi a me, {class}?", "Non dubito della sincerità di Danitha né del suo desiderio di guadagnare un posto tra i Reietti per quelli come te. Tuttavia, sospetto che non sarà l'ultima volta che vedremo uno dei tuoi fratelli e delle tue sorelle impazzire e rivolgere la Luce contro il proprio popolo.\n\nPotrebbe venire il momento in cui deciderò che tollerare il tuo ordine sciagurato non è più nell'interesse dei Reietti. Ti suggerisco di continuare a servire la tua gente con diligenza.\n\nVi terremo d'occhio.", 0x8a963535, 0x09f1d511, 0x27427458, 0x2d8b7e5f, 0x2b29670e, "....." },
  [95805] = { "La grazia di An'she e Mu'sha", "Porta lo Smoldering Incense al santuario di An'she e Mu'sha, sulle colline a sud-est, prima che l'incenso si riduca in cenere in dieci minuti!", "Il sole e la luna, An'she e Mu'sha, non fanno parte del nostro mondo come gli elementi, eppure la loro luce ci dà vita, guida e speranza.\n\nRendiamo omaggio agli spiriti del mondo, e così rendiamo omaggio anche ai gemelli.\n\nSe vuoi mostrare il tuo rispetto, prendi questo incenso fumante e portalo a un santuario sulle colline a sud-est, che domina la mesa, a sud dei verrospini. Fa' presto, così da raggiungere il santuario prima che l'incenso si consumi.\n\nNon bagnarlo!", "<Il fumo dell'incenso sale verso il cielo.>", "<Mentre versi l'incenso nel fuoco, il profumo si diffonde attorno a te, lasciandoti solo il sacchetto vuoto e un sottile senso di appagamento.>", 0x1483f5df, 0x82228fe2, 0x52a83811, 0xd4bc4ea6, 0xd28f1b93, "....." },
  [95809] = { "Intrecciato col cuore", "Torna da ⟦Caitlin Grassman=Caitlin Seccafieno⟧ al ⟦Menethil Harbor=Porto di Menethil⟧.", "Mi serve un momento di riposo prima di trovare da solo la strada per uscire.\n\n<Tira fuori dalla sacca alcune canne, le intreccia e le piega rapidamente a forma di cuore.>\n\nPrendi questo e portalo a Caitlin. Dille che tornerò presto a casa! Ora che grazie a te c'è un sentiero libero, raccoglierò i miei fasci e seguirò le tue tracce.\n\nGrazie.", "Sono in pensiero più che mai per lui!", "Santo cielo, sembra terribile!\n\nPer la Luce, sono grata che sia uno dei sopravvissuti.\n\n<Porta il cuore intrecciato di canne al proprio.>\n\nComincerò a cucinargli un pasto sostanzioso. Grazie per avermelo portato. Vorrei che tu avessi qualcosa come segno della nostra gratitudine.", 0x7c49eff3, 0xb6ab7769, 0x84c0de8c, 0xe6585009, 0x1b59b91e, "....." },
  [95810] = { "Il trasporto della reliquia perduta", "Porta la ⟦Titan Relic=Reliquia dei Titani⟧ al prospettore Whelgar, agli scavi delle ⟦Wetlands=Paludi Grigie⟧.", "Raccogli un pezzo spezzato dell'automa di roccia. Ha una consistenza diversa da qualsiasi cosa tu abbia mai toccato, un materiale composito di natura sconosciuta. Di certo è più \"congegno\" che \"rottame\".\n\nForse il prospettore Whelgar in persona, ai suoi scavi, potrà dirti qualcosa di utile sulla reliquia.", "Qui per lo scavo?", "Ah, ti sei spint<o/a> fin laggiù dentro e sei sopravvissut<o/a> per raccontarlo?! Vediamo cosa porti lì.\n\nBeh, sapendo cosa hai passato per riportarmelo, penso che il tuo manufatto meriti una certa reverenza.", 0x66a19050, 0x25ed1b64, 0x09d52652, 0xbc60563b, 0x58b3930c, "....." },
  [95816] = { "Iscrivimi!", "Porta il modulo compilato a Elaine Compton, nelle ⟦Redridge Mountains=Montagne Crestarossa⟧.", "Salve, stimat<o/a> artigian<o/a>!\n\nCompilando questo modulo otterrai un permesso non esclusivo, revocabile e giuridicamente limitato di esporre insegne pubblicitarie per le tue professioni in tutta Azeroth!\n\nUna volta compilato, portalo al coordinatore dei contratti della filiale locale dell'Azeroth Commerce Authority per avviare la pratica.\n\nBuon lavoro!", nil, nil, 0xe71188a6, 0xaef04737, 0x5eb40123, nil, nil, "...mm" },
  [95817] = { "⟦Rotgath Stonebeard=Rotgath Barbapietra⟧", "Incontra ⟦Rotgath Stonebeard=Rotgath Barbapietra⟧ vicino alla ⟦Great Forge=Grande Forgia⟧, a ⟦Ironforge=Forgiardente⟧.", "Hai mai conosciuto ⟦Rotgath Stonebeard=Rotgath Barbapietra⟧? È un fabbro nanico di ⟦Ironforge=Forgiardente⟧. Non è il tipo più loquace in circolazione, ma è sempre affidabile. Ci rivolgiamo spesso a lui quando ci servono grandi quantità di lavori dal disegno semplice, quelli che Stondry è troppo orgoglioso per accettare di persona.\n\nI suoi tempi di consegna sono eccellenti, soprattutto quando si tratta di aiutare nuovi artigiani ad avviare la propria bottega. Non affiderei a nessun altro la realizzazione rapida della tua insegna. Digli che ti mando io, se ti crea problemi!", nil, nil, 0xcc87f187, 0x29aa8c0c, 0x265b4cd5, nil, nil, "...mm" },
  [95818] = { "Un lavoretto veloce", "Porta i materiali richiesti a ⟦Rotgath Stonebeard=Rotgath Barbapietra⟧, vicino alla ⟦Great Forge=Grande Forgia⟧, a ⟦Ironforge=Forgiardente⟧.", "Possiamo sistemarti e rimetterti in strada in un attimo, purché tu abbia i materiali a portata di mano! Ci serviranno $N1 Lingotti di Mithril e $N2 ⟦Heavy Leather=Cuoio Pesante⟧. Di solito servono anche altri metalli e roba simile, ma ho qualche avanzo che occupa spazio e che possiamo usare per quei pezzi in più.\n\nAh, come favore personale, ti chiederò anche $N3 Goldthorn. Mia moglie conosce un'ottima ricetta per il tè e vorrei farle una sorpresa. Consideralo il tuo pagamento!", nil, nil, 0xae19085c, 0x93f08152, 0x8ce5bacd, nil, nil, "...mm" },
  [95819] = { "Iscrivimi!", "Porta il modulo compilato a Jornah, nelle ⟦The Barrens=Savane⟧.", "Salve, stimat<o/a> artigian<o/a>!\n\nCompilando questo modulo otterrai un permesso non esclusivo, revocabile e giuridicamente limitato di esporre insegne pubblicitarie per le tue professioni in tutta Azeroth!\n\nUna volta compilato, portalo al coordinatore dei contratti della Durotar Supply & Logistics della tua zona per avviare la pratica.\n\nBuon lavoro!", nil, nil, 0xe71188a6, 0x73fcb0bd, 0xb6355654, nil, nil, "...mm" },
  [95820] = { nil, "Incontra Karolek nel negozio dei Conciatori di Pelle di Kodo a Orgrimmar.", "Abbiamo fatto bene a creare ottimi rapporti con i mercanti e gli artigiani di Orgrimmar. Tra queste eccellenti relazioni c'è un orco di nome Karolek, un conciatore che ci assicura una fornitura costante di pelli e altro equipaggiamento utile.\n\nTra l'altro è anche bravissimo a fare insegne!\n\nSe vuoi far fare in fretta la tua insegna, ti consiglio lui più di chiunque altro. Digli che ti mando io.", nil, nil, 0x1d925e2f, 0xa57cb96d, 0xf99d6a4a, nil, nil, "e..mm" },
  [95821] = { "Una creazione rapida", "Porta i materiali richiesti a Karolek nel negozio dei Conciatori di Pelle di Kodo a Orgrimmar.", "I materiali per l'insegna dovrebbero essere facili da trovare per un artigiano esperto come te. Ci serviranno solo $N1 ⟦Heavy Leather=Cuoio Pesante⟧ e $N2 Lingotti di Mithril.\n\nDi solito per un ordine urgente chiederei qualche moneta d'oro, ma ultimamente mi è venuta voglia di ⟦Goldthorn Tea=Tè di Orospino⟧ fatto in casa. Non preoccuparti, mi piace prepararlo da me, ma ho bisogno di $N3 Orospino per farlo.\n\nSe mi porti tutto questo, avrai la tua prima insegna pronta in un batter d'occhio!", nil, nil, 0xae19085c, 0xe950caee, 0xa13e88d4, nil, nil, "...mm" },
  [95882] = { "RICERCATO: Capo Esploratore Vargas", "Porta l'Occhio del Capo Esploratore a Neza Grugnorosso a Rog'mar.", "Un gruppo di ricognizione dell'⟦Alliance=Alleanza⟧ è stato avvistato su una piccola isola a nord-est di Rog'mar. È guidato da un capo esploratore che ha reso sempre più difficile tracciare i movimenti nemici. Quel bastardo ha persino chiamato il suo sudicio famiglio con il mio nome come aperta presa in giro. Sa che gli do la caccia.\n\nQuesto umano ha occhi ovunque e vanno spenti. Ne ho già preso uno prima che riuscisse a fuggire. Portami l'altro come prova che il capo esploratore non esiste più. Mostragli che non è così intoccabile come pensa.\n\n-- Neza Grugnorosso", nil, nil, 0x14a2c256, 0x49cfe0ef, 0xdd3ba7f1, nil, nil, "...mm" },
  [95883] = { "L'anima tormentata", "Raccogli un'⟦Tortured Soul=Anima Torturata⟧ dai non morti vicini, alla ⟦Beren's Peril=Grotta di Beren⟧, nella ⟦Silverpine Forest=Selva Pinargento⟧.", "<I preparativi per un rituale allestito in fretta sono ammucchiati senza cerimonie sull'altare. Secondo il frammento di biglietto, è stato raccolto tutto. Mancano solo l'offerta di sangue e l'anima tormentata.\n\nI non morti attorno a te sembrano abbastanza tormentati. Potrebbero avere ciò che cerchi.>", "<La pietra delle offerte è minacciosamente immobile.>", "<In presenza della pietra delle offerte, l'anima tormentata sprigiona un'energia immonda.\n\nSembra che tu sia più vicin<o/a> a compiere il rituale.>", 0xb60b70e3, 0x0d080853, 0x972297ea, 0x03dfcb1a, 0x2d800f13, "....." },
  [95884] = { "La pietra delle offerte", "Trova la pietra delle offerte alla ⟦Beren's Peril=Grotta di Beren⟧, nella ⟦Silverpine Forest=Selva Pinargento⟧.", "<Il frammento di biglietto è quasi tutto illeggibile. Ciò che si legge ancora, però, sono appunti sui preparativi per un'offerta.\n\nVi si menzionano una pietra delle offerte e un rituale.\n\nForse puoi trovare questa pietra delle offerte qui vicino.>", nil, "<Strani strumenti e oggetti ingombrano la superficie ruvida della pietra.\n\nQuesta è di certo la pietra delle offerte menzionata nel biglietto.>", 0xa6de587b, 0x975b0b28, 0x838aeea9, nil, 0xaa91f891, "...m." },
  [95885] = { "L'offerta di sangue", "Usa l'⟦Tortured Soul=Anima Torturata⟧ per compiere un'offerta di sangue alla pietra delle offerte, nella ⟦Beren's Peril=Grotta di Beren⟧.", "<Ora manca solo l'offerta di sangue.\n\nIl frammento di biglietto parlava di un \"sacrificio volontario\".\n\nUn intenso senso di terrore ti pervade.>", "<La pietra delle offerte è minacciosamente immobile.>", "<Ora la pietra delle offerte è inerte. Sembra che il tuo rituale l'abbia prosciugata del suo potere. A quale scopo, non lo sai, ma ormai è finita.\n\nLa pietra ruvida si crepa e si sgretola, ormai priva di scopo.\n\nQualcosa luccica tra i resti...>", 0x3785a093, 0x7d15beec, 0xb34b8754, 0x03dfcb1a, 0x73aa5f70, "....." },
  [95912] = { "RICERCATO: Maestro di Spade Kaijo", "Porta lo Stendardo del Maestro di Spade a Ember Soffialama a Forte Farholde.", "Per ogni orco che abbattiamo, un altro prende il suo posto, in qualche modo ancora più capace del precedente. Un guerriero esperto deve addestrare questa nuova generazione. Se vogliamo fare breccia nei loro numeri, dobbiamo assicurarci che non abbiano modo di recuperare le perdite.\n\nSe qualche soldato è abbastanza coraggioso, è fondamentale trovare questo maestro di spade e mettergli fine. Probabilmente è proprio ora al campo reclute a nord dell'avamposto dell'⟦Horde=Orda⟧. Uccidilo, prendi il suo stendardo e distruggi il morale degli orchi.\n\n-- Ember Soffialama", "La minaccia degli orchi sembra non finire mai, e la determinazione dei nostri soldati vacilla. Se non facciamo presto qualcosa riguardo ai loro capi, temo che questa battaglia sarà finita prima ancora di iniziare.", "Acciaio e rifornimenti vincono le battaglie, ma sono i cuori e le menti a vincere le guerre. Con questo stendardo mostreremo alle nostre reclute che l'Orda non è nulla da temere.\n\nBel lavoro, {name}.", 0xcaa9a163, 0x66f86f32, 0x5fdbd226, 0x6618272b, 0xefdc855f, "....." },
  [95913] = { "Degno di una principessa", "Raccogli $N1 Pelliccia di Coyote per Tessa Albachiara a Forte Farholde.", "<Tessa culla la sua bambina, cercando di farla addormentare.>\n\nSe non ha fame, forse è solo stanca. A dire il vero, Emma è stata una splendida sorpresa, ma questo significa che eravamo un po' impreparati. Mio marito le ha costruito questa bella culla, ma temo che queste coperte siano troppo vecchie. Si merita il meglio, dopotutto.\n\nSe hai ancora voglia di aiutare, ti sarei grata per sempre se riuscissi a trovare delle pelli per foderarle il lettino. Se questo la fa smettere di piangere, credo che tutta Farholde ti sarebbe riconoscente.", "<Tessa non alza lo sguardo mentre cerca disperatamente di far addormentare la sua bambina che piange.>\n\nShh, shh. <Il/La> {class} gentile e forte ci aiuterà mentre papà è via.", "Oh, sei tornat<o/a>! Sei un miracolo, {name}. Sembrano così caldi e invitanti... e morbidi.\n\n<Tessa sbatte stancamente le palpebre. Sembra che non dorma da giorni.>\n\nPer Emma, ovviamente.", 0x3787da47, 0x126c5316, 0xf43a5774, 0x4b77091f, 0x14512c82, "....." },
  [95924] = { "Panico al sito di scavo", "Uccidi 6 Devasauro Matriarca, 9 Devasauro Pellegrama e Crestavelenosa nella Terrazza del Plasmatore.", "Ehi tu! Sì, dico proprio a te! Abbiamo fatto la scoperta di una vita giù a Un'Goro! Ci credi?\n\nC'è solo un problema... il nostro sito di scavo è stato invaso da bestie voraci di natura assassina. Molto spiacevole, davvero.\n\nCon il tuo aiuto possiamo riprenderci il nostro accampamento e tornare al lavoro. Allora, che ne dici? Ne varrà la pena per te.", nil, nil, 0xb52b6bf6, 0xa9abb6aa, 0xc87d885f, nil, nil, "...mm" },
  [95925] = { "Mappare la strada da seguire", "Trova i punti di riferimento interessanti nella Terrazza del Plasmatore e compila la mappa dell'esploratore in ciascuno.", "{class}, abbiamo fatto la scoperta di una vita! Non ci credo: le rovine di Un'Goro sono aperte!\n\nAbbiamo già mandato una squadra ma ha incontrato... problemi. Se ci stai andando comunque, potresti finire questa mappa?\n\nSembra che lì dentro ci sia un Cristallo Acromatico e un guardiano dissepolto da qualche parte vicino a un gigantesco Cancello Occidentale che suona interessante.\n\nGli altri punti di riferimento che sarebbero utili sono il Pilastro dell'Assimilazione, il Western Gate e il Vestibolo della Ricrescita.", nil, nil, 0x1550c0b7, 0x9e31dad0, 0x0004535d, nil, nil, "...mm" },
  [95926] = { "Il Cristallo Oscuro", "Raccogli un Frammento di Cristallo Prosciugato incolore vicino al Cristallo Acromatico nella Terrazza del Plasmatore.", "Ehi tu! Ho un lavoro per qualcuno con le tue... capacità.\n\nHo saputo dalle mie fonti di un cristallo trovato nella Terrazza del Plasmatore che sembra in grado di drenare gli elementi che lo circondano. O forse può drenare l'essenza vitale stessa. Dal rapporto non è chiaro.\n\nDevo avere un frammento di questo cristallo! Pensa alle applicazioni di un artefatto così potente.\n\nVai alla Terrazza del Plasmatore e portami un campione di questo Cristallo Acromatico incolore, e ti ricompenserò per i tuoi sforzi.", nil, nil, 0x2d2c4ed7, 0x0f519b46, 0x96cb793a, nil, nil, "...mm" },
  [95928] = { "Elementi cristallini", "Porta a Mayena Cercaterra un Cristallo Umido, un Cristallo Caricato, un Cristallo Nocivo e un Cristallo Ardente dalla Terrazza del Plasmatore.", "Ah, è un bene che tu sia venuto qui, {class}.\n\nHo studiato i cristalli ultimamente e mi è giunta voce di un insieme particolare di cristalli che si dice provengano dal ⟦Un'Goro Crater=Cratere di Un'Goro⟧. Ho campioni di quelli più semplici, ma ho sentito parlare di cristalli più grandi e potenti visti in un luogo chiamato Terrazza del Plasmatore.\n\nNon so molto di questo posto, a parte il fatto che contiene questi cristalli che a quanto pare racchiudono gli elementi stessi. Se ti trovi lì, portami per favore un campione di ciascun colore.", nil, nil, 0x66b9ce44, 0x7ff02a97, 0xbb662c2b, nil, nil, "...mm" },
  [95934] = { "La Prova del Profitto", "Trova un pezzo di ⟦Cubic Draconia=Draconia Cubica⟧ per ⟦Gelinda Coppergleam=Gelinda Lucerame⟧.", "I miei strumenti di rilevamento segnalano tracce di un minerale mai visto prima in queste caverne. Lo chiamo draconia cubica. Probabilmente vale una fortuna.\n\nPer quanto sia una scoperta entusiasmante, nessuno verrà ad aiutarmi a scavarla se non posso dimostrare che esiste. Certo, ho le letture dei miei strumenti, ma alla gente piace stringere in mano un grosso cristallo luccicante, non guardare dei grafici.\n\nSono sicura che là dentro qualche cristallo spunta dalla terra. Se te la senti di schivare qualche drago e procurarmene uno, daresti davvero una mano a una ragazza.", "A dire il vero, non so se la draconia cubica si possa semplicemente strappare dal terreno a mani nude. Se hai problemi a recuperarne un po', torna qui e ti presto della dinamite.", "Perbacco! Questo farà girare qualche testa! Bel lavoro a scavarlo. C'è un posto nella squadra mineraria per te, se mai ti interessasse.", 0x40c81f11, 0x0e60bf69, 0xc68aae30, 0xda57cb0c, 0x6603da29, "....." },
  [95935] = { "Gloria all'ammazzadraghi", "Porta la Testa di Scaldaron a Cedric Dalton alla Guardia Meridionale.", "La testa del drago è tutta denti, scaglie e cenere: un macabro trofeo preso da una macabra creatura. Tenendola in mano, senti il calore del suo ultimo respiro infuocato ancora irradiarsi dalle fauci.\n\nSebbene la minaccia che Scaldaron rappresentava non esista più, le sentinelle della Guardia Meridionale dovrebbero sapere cos'è successo qui.", nil, nil, 0xfa82d67b, 0x50eaae30, 0xd2d0f558, nil, nil, "...mm" },
  [95936] = { "Gloria all'ammazzadraghi", "Porta la Testa di Scaldaron a Krom'rosh a Rog'mar.", "La testa del drago è tutta denti, scaglie e cenere: un macabro trofeo preso da una macabra creatura. Tenendola in mano, senti il calore del suo ultimo respiro infuocato ancora irradiarsi dalle fauci.\n\nSebbene la minaccia che Scaldaron rappresentava non esista più, i guerrieri di Rog'mar dovrebbero sapere cos'è successo qui.", nil, nil, 0xfa82d67b, 0x675d23ae, 0xc4b52099, nil, nil, "...mm" },
  [95943] = { "Il guaio del caposquadra", "Trova la Cassa del Caposquadra e riportala a Bertrand Fronte Dura a Forte Farholde.", "Salve, <ragazzo/ragazza>. Mi chiamo Bertrand, Bertrand Fronte Dura! Al tuo servizio.\n\n<Bertrand tende una mano sporca.>\n\nQuesta brava gente mi ha ingaggiato per sovrintendere alla costruzione di questo forte. Quello che manca loro in esperienza lo compensano con lo spirito! Il problema è che ho perso i miei attrezzi.\n\nHo avuto un piccolo scontro con alcuni del Crepuscolo in un boschetto a nord-ovest di qui. Ho dovuto scegliere tra la vita e i miei attrezzi. Da un lato, sono vivo. Dall'altro... vedi dove si va a parare.\n\nPensi di potermi aiutare a ritrovare i miei attrezzi?", "Hai trovato le mie cose?", "<Bertrand apre la cassa ed estrae un boccale e un barilotto di birra.>\n\nEcco la roba buona! Rimetteremo in piedi questo forte in un baleno! Mi hai salvato la vita, <ragazzo/ragazza>.", 0xd5e9d9a6, 0x3a069aaa, 0x8c54f8b0, 0xe7956f2b, 0x2fcae8d2, ".....", nil, nil, 0x84fbc76c, nil, nil },
  [95951] = { "Raccogli e impennaggia", "Raccogli le Fascine di Legna dalle cataste di legna dei contadini al Campo di Disboscamento di Turner, poi lavorale per ottenere $N1 Lancia Infilzatutto Improvvisata.", "Ehi, <capo/capa>, ti serve aiuto dal vecchio Tan'jani? Non preoccuparti, ti sistemo io bene.\n\nGli orchi sono bravi a colpire gli umani con le asce, ma quando vuoi infilzarli prima che ti vedano arrivare, è allora che chiami i cacciatori di teste. Vuoi imparare anche tu a infilzarli? Lo vedo nei tuoi occhi, eheh.\n\nPrima ti procuriamo le tue lance. Questa è mia. Vai all'accampamento degli umani a ovest e prendi il loro legno. Porta il coltello con te. Puoi affilare la loro legna in buone lance per infilzare. Poi riportale qui.", nil, nil, 0x4fc22b5d, 0x57766d88, 0x551f1aa2, nil, nil, "...mm", nil, nil, 0xa19e88f8, nil, nil },
  [95955] = { "Infilzali", "Trafiggi $N1 Crocolisco d'Acqua Dolce, poi torna da Tran'jani a Rog'mar.", "Hai le lance, ora impari a lanciarle.\n\nLe Radure del Fiume sono piene di crocolischi. Brutte bestie. Ti azzannano se non sei svelto. Perfetti per l'allenamento al bersaglio, eheh.\n\nVai a infilzarne un bel po'. Poi torni dal vecchio Tan'jani per il tuo premio. Se riesci a infilzare un crocolisco, riesci a infilzare qualsiasi cosa.", nil, nil, 0xef8d9e70, 0x7f7a7f96, 0x85cc29a7, nil, nil, "...mm" },
  [95957] = { "Bevi fino in fondo!", "Consegna il Boccale Spumeggiante di Zizplink a Gray Albachiara al Porto Polveraccesa.", "Ecco qua, campione. Un drink per quel vecchio brontolone laggiù. Se questo non lo fa tornare sobrio, niente lo farà.\n\nAh, e uh... lavati le mani dopo averlo toccato. E non farlo finire negli occhi.", nil, nil, 0xfd1d5424, 0x84763129, 0xa533783b, nil, nil, "...mm" },
  [95961] = { "Fuori per un momento", "Trova Gray Albachiara al Porto Polveraccesa.", "<La bambina di Tessa continua a strillare forte.>\n\nImmagino che non sia stanca. Oh... tutti fanno sembrare tutto così facile. Suo padre sa sempre come tirarla su di morale. Se solo tornasse a casa.\n\n{name}, mi dispiace chiederlo, ma puoi vedere cosa lo sta trattenendo tanto? È uscito un po' di tempo fa ma dovrebbe essere già tornato. Emma si illumina quando lo vede.\n\nDovresti trovarlo al Porto Polveraccesa: ultimamente sembra andarci spesso. Riconoscerai il mio Gray quando lo vedrai. Brilla come il sole.", nil, "Ti ha mandato Tess? No... Non posso tornare a casa. Non riesco a guardarle in faccia.\n\nCome abbiamo potuto mettere al mondo una bambina? Non possiamo proteggerla. A malapena riusciamo a proteggere noi stessi. Che futuro possiamo prometterle? Altre guerre? A cosa stavamo pensando...\n\nTi prego, non dirlo a Tessa. Tornerò più tardi. Prima o poi.\n\nMi serve solo un altro drink.", 0x8ccc9729, 0x27b9866b, 0x9432dd15, nil, 0x6f03367d, "...m." },
  [95975] = { "Il suo mondo", "Raccogli $N1 Fiore Selvatico e consegnali a Tessa Albachiara a Forte Farholde.", "Tess dice che la piccola Emm non riesce a dormire senza di me? E tu hai fatto tutto questo per loro? Un perfetto sconosciuto? Dannazione. A cosa stavo pensando...\n\nAnche se non posso garantirle un mondo perfetto, devo comunque farne parte. Per cosa combatto, se non posso sperare in un futuro più luminoso?\n\nGrazie per aver aiutato la mia famiglia in mia assenza, amico, ma è ora che io torni a casa. Se potessi chiederti un altro favore, puoi raccogliere dei fiori e portarli a Tess? Falle sapere che tornerò presto. Prima devo darmi una ripulita.", nil, nil, 0xcc35dd84, 0xeded6ec0, 0xdd8a0d2e, nil, nil, "...mm" },
  [95981] = { "Sorvegliare le strade", "Uccidi $N1 Dalaran Wizard e $N2 Dalaran Watcher per il ⟦Shadow Priest Allister=Sacerdote dell'Ombra Allister⟧, alla ⟦Sepulcher=Mausolea⟧.", "Togliere loro i pendenti è solo il primo passo. Se il Kirin Tor sta davvero spedendo da Dalaran un flusso costante di reliquie, dobbiamo fermarli alla fonte.\n\nCerca i maghi e i guardiani di Dalaran lungo le strade attorno a ⟦Ambermill=Mulino d'Ambra⟧. La loro presenza ha permesso per troppo tempo il libero passaggio attraverso i nostri confini. Se riusciamo a sfoltirne le fila, questi pendenti dovrebbero smettere di arrivare nella ⟦Silverpine Forest=Selva Pinargento⟧ fin dall'inizio.", nil, "Da quando è caduta la barriera attorno a Dalaran, il Kirin Tor tiene le strade in una morsa mortale. Hanno paura di qualcosa, questo è certo.\n\nPer ora, però, il perché non ha importanza.", 0xda0a241c, 0x94f2addc, 0x6d26148a, nil, 0xf9405a42, "...m." },
  [95982] = { "Non Sono Affari Miei", "Porta $N1 ⟦Briny Seafood Stew=Stufato di Mare Salmastro⟧ a ⟦Jasper Geartoggle=Jasper Levaingranaggi⟧ a ⟦Powderfuse Port=Porto Polveraccesa⟧.", "La gente continua a mollarmi qui i suoi amici pelosi, come se sapessi cosa sto facendo. E poi se la prendono con me se tornano e il loro cavallo o il loro lupo o... qualunque cosa si siano portati dietro è morto o è scappato. Per chi mi hanno preso, per un ente di beneficenza?\n\nTu sembri un tipo che se ne intende di mangiatoie. Ti va di prepararmi un po' di sbobba per tenere a bada queste bestiole?\n\nSe non sai prepararla da te, magari qualcuno te la vende. E sbrigati! L'ultima cosa che mi serve è una mandria di animali affamati in fuga.", nil, nil, 0x16d2f3a7, 0xd8268884, 0x6b04a804, nil, nil, ".s.mm" },
  [95983] = { "Un banchetto per gli avvoltoi", "Porta il Teschio Rosicchiato al guardiano Cornelius al Presidio di Terral.", "Lo scheletro è ridotto a brandelli. Segni profondi sugli arti corrispondono vagamente a impronte di denti e artigli. Molti giorni sotto il sole cocente hanno reso le ossa anche pallide e fragili. La brutalità sia dell'aggressore sia del clima ha reso un mistero l'identità della vittima.\n\nNon puoi portare via l'intero scheletro, ma potresti portare il suo teschio alla guardia qui vicino e vedere cosa sa.", "E ora che c'è?", "<Cornelius passa le dita sui segni lasciati sul teschio. Più lo fa, più si acciglia.>\n\nProprio ciò che mi serviva... altro lavoro. Mi hai messo in un bel guaio, lo sai?", 0x3042c70f, 0x440cdf2d, 0x26ed9b26, 0x6c553a1f, 0xabfa4f3d, "....." },
  [95984] = { "Il canto dello zampalunga", "Porta un Becco di Zampalunga Intatto al guardiano Cornelius al Presidio di Terral.", "Questi segni sono di un leone. A giudicare da essi, questo è particolarmente grosso. Il capo del vicino branco, con ogni probabilità.\n\nSe si diffonde la voce di un leone mangiatore di uomini che si aggira sotto la mia guardia, Demar andrà su tutte le furie. Per fortuna ho un piano.\n\nPosso fabbricare un fischietto che imita il richiamo di uno zampalunga ferito. Possiamo usarlo per attirare fuori la bestia. Mi servirà solo uno dei loro becchi per dargli il suono giusto. Ci sono zampalunga per tutte le pianure. Portami un becco, e che sia in fretta!", "Penso sia superfluo dirlo, ma sarai tu a usare questo fischietto.", "Bene, allora. Lasciami solo un momento, così lo intaglio nella forma giusta.", 0x37a5cbb4, 0x60e2eaf1, 0xc54240a1, 0x35a63f60, 0xd5ff9a49, "....." },
  [95986] = { "Re delle pianure selvagge", "Usa il Richiamo per Zampalunga per attirare il capo del branco di leoni. Uccidi la bestia e recupera la sua pelle per il guardiano Cornelius al Presidio di Terral.", "Il fischietto è pronto, {name}.\n\nPrendilo e vai in cima alla collina dove stanno i leoni. Dovrebbe essere subito a nord di qui.\n\nUna volta lì, soffia nel fischietto e il nostro mangiatore di uomini dovrebbe apparire. Ti direi di non tornare se non riesci a ucciderlo, ma probabilmente sarai morto comunque.\n\nOra vai. Vediamo se te la cavi meglio del nostro amico scheletro.", "Se ti rivolgi a me, presumo che il leone sia stato ucciso.", "Ah, è proprio così! In tal caso, ben fatto.\n\nGiusto per essere chiari... siamo d'accordo che questa faccenda non deve arrivare a Demar, giusto? Direi che ce la siamo cavata benissimo da soli.\n\nQuell'uomo mi ha già mandato in questo posto. Non mi serve altra attenzione speciale da parte sua.", 0xc62bac87, 0x712e2e61, 0xb8006b01, 0xd4db3e84, 0xffc99f6c, "....." },
  [95988] = { "Scende giù liscia", "Raccogli $N1 Sputo di Crostaceo, Interiora Fresche, Sgrassatore Goblin e Veleno Scaduto per il locandiere Zizplink al Porto Polveraccesa.", "Hai parlato con Gray, eh? Un vero spasso, quel tizio. L'ultima cosa che gli serve è che tu gli porti un altro drink. Questa è una locanda, non un bar. È fortunato che non l'abbia ancora buttato fuori.\n\nSe vuoi portartelo via, accomodati. Anche se non credo sia in condizioni di andare da nessuna parte così. Non senza un piccolo ricostituente goblin.\n\nPerché non mi raccogli qualche ingrediente da questa lista mentre preparo al tuo piccolo amico il suo \"drink\"? Vedremo se vorrà ancora alcol dopo aver provato il mio cocktail speciale.", nil, nil, 0x5b034a84, 0xc7482903, 0x7e050bd9, nil, nil, "...mm" },
  [95991] = { "RICERCATO: Fauciaspettro", "Porta la Zanna di Fauciaspettro a Wheatley a Forte Farholde.", "È già abbastanza pericoloso trasportare cavalli per le radure senza le voci di un misterioso crocolisco fantasma che mi azzanna i miei pregiati pony! Dicono che questo sia grande almeno tre volte un crocolisco normale. E due volte più cattivo!\n\nNon sono uno che scommette. Non rischio i miei cavalli finché qualcuno non abbatte questo mostro buono a nulla. Se qualcuno trova questo malfattore lungo i fiumi, mi porti il suo dente così so che è sicuro viaggiare di nuovo. Fino ad allora, resto qui!\n\n-- Wheatley", nil, nil, 0x4beff704, 0x6eb2b2fa, 0xd393462b, nil, nil, "...mm" },
  [95992] = { "RICERCATO: Fauciaspettro", "Porta la Zanna di Fauciaspettro a Tan'jani a Rog'mar.", "Queste acque sono insidiose. I miei cacciatori di teste tengono i sentieri liberi come possono, ma c'è una bestia che si aggira nei fiumi che nemmeno noi riusciamo a prendere. Emozionante, eh?\n\nIl capo dice che dobbiamo ripulire, quindi abbiamo una piccola gara in corso. Trova quello bianco che pattuglia i fiumi e portami la sua zanna. Chi infilza questo viscido crocolisco vince tutta la posta. Basta che non ti faccia azzannare tu, eheh!\n\n-- Tan'jani", nil, nil, 0x4beff704, 0x52246dda, 0x1da17cbe, nil, nil, "...mm" },
  [95998] = { "La vita all'aria aperta", "Siediti vicino al ⟦Sam's Basic Campfire=Fuoco da Campo Semplice di Sam⟧ e attendi di ricevere il beneficio ⟦Boosted Rest=Riposo Potenziato⟧.", "Be', salve, {class}. Si vede che hai l'aria dell'avventuriero. Buon per te. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nIl mondo là fuori è grande e vasto, e per farcela dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma credo di poterti insegnare un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", "Avere le capacità necessarie per sopravvivere all'aria aperta è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere? Ti insegneranno anche come costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xd61f22e7, 0xd463b94a, 0x452722a2, 0x1938d14a, "....." },
  [95999] = { "RICERCATO: Incinerator Gar'im", "Consegna il ⟦Broken Staff of Incinerator Gar'im=Bastone Spezzato dell'Inceneritore Gar'im⟧ al magistrato Solomon a ⟦Lakeshire=Borgolago⟧.", "Ricercato! Incinerator Gar'im, capo di un'incursione di orchi nella ⟦Render's Valley=Valle di Rend⟧. Si sospetta che collabori con i ⟦Blackrock=Roccianera⟧ del ⟦Stonewatch Keep=Mastio di Guardamasso⟧.\n\nAttenzione a Incinerator Gar'im. Lui e i suoi incantatori dell'ombra sono estremamente pericolosi. Una generosa ricompensa andrà a qualunque anima coraggiosa sappia consegnare al magistrato Solomon la prova della morte di Incinerator Gar'im.", "Che cos'hai lì, {race}?", "Ottimo lavoro, {name}! Incinerator Gar'im si preparava a rafforzare le difese del ⟦Stonewatch Keep=Mastio di Guardamasso⟧. Con questa vittoria, potremmo ancora riuscire a riconquistare il mastio!", 0xfbb45123, 0x39291674, 0x96bd3b4a, 0x46dc827d, 0xaf05c26e, "....." },
})
